INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (1, 'cn', '1', '', '公司简介', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:26:11', '', '', '', '<p><br /></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul class=\"list-paddingleft-2\"><li><p>区域管理（多语言）</p></li><li><p>模型管理（自定义内容模型）</p></li><li><p>模型字段管理（自定义模型字段）</p></li><li><p>栏目管理</p></li><li><p>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p>站点配置、公司信息</p></li><li><p>定制标签（自定义前台标签）</p></li><li><p>前台模版标签</p></li><li><p>轮播图片</p></li><li><p>多条件筛选</p></li><li><p>网站地图（sitemap）</p></li><li><p>友情链接</p></li><li><p>自定义表单</p></li><li><p>留言信息</p></li><li><p>文章内链</p></li><li><p>多条件搜索</p></li><li><p>内容权限</p></li><li><p>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p>会员字段</p></li><li><p>会员等级(设置栏目与内容浏览权限)</p></li><li><p>文章评论(回复、审核)</p></li><li><p>我的评论</p></li></ul>', '', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模...', 255, '1', '0', '0', '0', 2764, 0, 0, 'admin', 'admin', '2018-04-11 17:26:11', '2025-11-07 11:56:19', '4', '', '', '36', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (3, 'cn', '11', '', '联系我们', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:31:29', '/static/upload/image/20180413/1523583018133454.png', '', '', '联系我们', '', '', '', '官方网站：www.badoucms.com技术交流群： 137083872www.badoucms.com我们一直秉承大道至简分享便可改变世界的理念，坚持做最简约灵活的badoucms开源软件！', 255, '1', '0', '0', '0', 144, 0, 0, 'admin', 'admin', '2018-04-11 17:31:29', '2025-11-07 11:56:16', '4', '', '', '37', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (278, 'en', '125', '', 'Contact Us', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:31:29', '/static/upload/image/20180413/1523583018133454.png', '', '', 'Contact Us', '', '', '', 'Official website: www.badoucms.com Technical exchange group: 137083872www.badoucms.com We have always been adhering to the concept that simplicity is the key and sharing can change the world, and insist on making the most simple and flexible badoucms open source software!', 255, '1', '0', '0', '0', 161, 0, 0, 'admin', 'admin', '2018-04-11 17:31:29', '2025-11-03 09:52:26', '4', '', '', '37', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (233, 'en', '104', '', 'What is the delivery time?', '', '', '', '', '', '', '2025-10-24 14:47:48', '', '', '', 'Sample lead time is approximately 7 days. Mass production lead time is 20-30 days after receiving the deposit. Lead time begins after we receive your deposit and obtain your final approval of the product. If our lead time does not meet your deadline, please confirm your requirements at the time of sale. In all cases, we will do our best to meet your needs, and in most cases, we are able to do so.', '', '', '', 'Sample lead time is approximately 7 days. Mass production lead time is 20-30 days after receiving the deposit. Lead time begins after we receive your deposit and obtain your final approval of the product. If our lead time does not meet your deadline, please confirm your requirements at the time of s...', 0, '1', '0', '0', '0', 1, 0, 0, 'admin', 'admin', '2025-10-24 14:48:34', '2025-10-29 08:37:08', '', '', '', '3', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (146, 'cn', '84', '', '交货时间是多少？', '', '', '', '', '', '', '2025-10-24 14:47:48', '', '', '', '样品交付周期约为7天。批量生产交付周期为收到定金后20-30天。交付周期在我们收到您的定金并获得您对产品的最终批准后生效。如果我们的交付周期未能满足您的截止日期，请在销售时确认您的要求。在任何情况下，我们都会尽力满足您的需求。大多数情况下，我们都能做到。', '', '', '', '样品交付周期约为7天。批量生产交付周期为收到定金后20-30天。交付周期在我们收到您的定金并获得您对产品的最终批准后生效。如果我们的交付周期未能满足您的截止日期，请在销售时确认您的要求。在任何情况下，我们都会尽力满足您的需求。大多数情况下，我们都能做到。', 0, '1', '0', '0', '0', 0, 0, 0, 'admin', 'admin', '2025-10-24 14:48:34', '2025-10-27 17:25:04', '', '', '', '3', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (234, 'oe', '105', '', 'Wie lange dauert die Lieferung?', '', '', '', '', '', '', '2025-10-24 14:47:48', '', '', '', 'Die Lieferzeit für Muster beträgt ca. 7 Tage. Die Lieferzeit für die Massenproduktion beträgt 20–30 Tage nach Eingang der Anzahlung. Die Lieferzeit beginnt nach Eingang Ihrer Anzahlung und Ihrer endgültigen Produktfreigabe. Sollte unsere Lieferzeit nicht Ihren Vorgaben entsprechen, bestätigen Sie Ihre Anforderungen bitte zum Zeitpunkt des Verkaufs. Wir werden unser Bestes tun, um Ihre Anforderungen zu erfüllen, und in den meisten Fällen gelingt uns dies auch.', '', '', '', 'Die Lieferzeit für Muster beträgt ca. 7 Tage. Die Lieferzeit für die Massenproduktion beträgt 20–30 Tage nach Eingang der Anzahlung. Die Lieferzeit beginnt nach Eingang Ihrer Anzahlung und Ihrer endgültigen Produktfreigabe. Sollte unsere Lieferzeit nicht Ihren Vorgaben entsprechen, bestätigen...', 0, '1', '0', '0', '0', 0, 0, 0, 'admin', 'admin', '2025-10-24 14:48:34', '2025-10-27 17:25:03', '', '', '', '3', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (227, 'en', '113', '', 'badoucms officially launched version 1.0.0', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/d04eedf5fa381fbf8779592ad3783375.jpeg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p><img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" /></p><h3>Introduction</h3><p>BadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel images, multi-condition filtering, site map, etc. </p><h3>Feature List</h3><ul class=\"list-paddingleft-2\"><li><p>Region management (multi-language)</p></li><li><p>Model management (custom content model)</p></li><li><p>Model field management (custom model field)</p></li><li><p>Column management</p></li><li><p>Content management (single page content, article content, product content...custom content model)</p></li><li><p>Site configuration, company information</p></li><li><p>Custom tags (custom front-end tags)</p></li><li><p>Front-end template tags</p></li><li><p>Carousel images</p></li><li><p>Multi-condition filtering</p></li><li><p>Site map (s </p></li><li><p>Friendly links</p></li><li><p>Custom forms</p></li><li><p>Message information</p></li><li><p>Article internal links</p></li><li><p>Multi-condition search</p></li><li><p>Baidu push</p></li><li><p>Content permissions</p></li><li><p>Member functions (login, register, retrieve password, change password, balance, points, log out)</p></li><li><p>Member fields</p></li><li><p>Member level (set column and content browsing permissions)</p></li><li><p>Article comments (reply, review)</p></li><li><p>My comments</p></li></ul>', 'badoucms,a,b', '', '', 'IntroductionBadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comme...', 11, '1', '0', '0', '0', 36, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:53', '4', '', '请先充值', '22', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (228, 'oe', '114', '', 'badoucms hat Version 1.0.0 offiziell veröffentlicht', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/d04eedf5fa381fbf8779592ad3783375.jpeg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p><img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" /></p><h3>Einführung</h3><p>BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu Push, Karussellbilder, Filterung mit mehreren Bedingungen, Sitemap usw. </p><h3>Funktionsliste</h3><ul class=\"list-paddingleft-2\"><li><p>Regionsverwaltung (mehrsprachig)</p></li><li><p>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Modellfeldverwaltung (benutzerdefiniertes Modellfeld)</p></li><li><p>Spaltenverwaltung</p></li><li><p>Inhaltsverwaltung (Einzelseiteninhalt, Artikelinhalt, Produktinhalt ... benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Site-Konfiguration, Unternehmensinformationen</p></li><li><p>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</p></li><li><p>Front-End-Vorlagen-Tags</p></li><li><p>Karussellbilder</p></li><li><p>Mehrere Bedingungen Filterung</p></li><li><p>Sitemap (s </p></li><li><p>Freundliche Links</p></li><li><p>Benutzerdefinierte Formulare</p></li><li><p>Nachrichteninformationen</p></li><li><p>Interne Artikellinks</p></li><li><p>Suche mit mehreren Bedingungen</p></li><li><p>Baidu Push</p></li><li><p>Inhaltsberechtigungen</p></li><li><p>Mitgliederfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</p></li><li><p>Mitgliederfelder</p></li><li><p>Mitgliedsebene (Berechtigungen zum Durchsuchen von Spalten und Inhalten festlegen)</p></li><li><p>Artikelkommentare (Antworten, Überprüfen)</p></li><li><p>Meine Kommentare</p></li></ul>', 'badoucms,a,b', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsf...', 11, '1', '0', '0', '0', 36, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:53', '4', '', '请先充值', '22', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (229, 'jp', '115', '', 'badoucms バージョン 1.0.0 が正式にリリースされました', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/d04eedf5fa381fbf8779592ad3783375.jpeg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p><img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" /></p><h3>はじめに</h3><p>BadouCMSは、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plusなどの一般的なテクノロジースタックをベースにしたオープンソースのWebサイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像、多条件フィルタリング、サイトマップなどをサポートしています。</p><h3>機能一覧</h3><ul class=\"list-paddingleft-2\"><li><p>地域管理（多言語）</p></li><li><p>モデル管理（カスタムコンテンツモデル）</p></li><li><p>モデルフィールド管理（カスタムモデルフィールド）</p></li><li><p>列管理</p></li><li><p>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</p></li><li><p>サイト構成、会社情報</p></li><li><p>カスタムタグ（カスタムフロントエンドタグ）</p></li><li><p>フロントエンドテンプレートタグ</p></li><li><p>カルーセル画像</p></li><li><p>多条件フィルタリング</p></li><li><p>サイトマップ（s </p></li><li><p>フレンドリーリンク</p></li><li><p>カスタムフォーム</p></li><li><p>メッセージ情報</p></li><li><p>記事内部リンク</p></li><li><p>複数条件検索</p></li><li><p>Baiduプッシュ</p></li><li><p>コンテンツ権限</p></li><li><p>メンバー機能（ログイン、登録、パスワードの取得、パスワードの変更、残高、ポイント、ログアウト）</p></li><li><p>メンバーフィールド</p></li><li><p>メンバーレベル（列とコンテンツの閲覧権限の設定）</p></li><li><p>記事コメント（返信、レビュー）</p></li><li><p>私のコメント</p></li></ul>', 'badoucms,a,b', '', '', 'はじめにBadouCMSは、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plusなどの一般的なテクノロジースタックをベースにしたオープンソースのWebサイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像、多...', 11, '1', '0', '0', '0', 36, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:53', '4', '', '请先充值', '22', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (230, 'en', '113', '', 'badoucms feature list', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '', '', '<p><br /></p><h3>Introduction</h3><p>BadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel, multi-condition filtering, site map, etc. </p><h3>Feature List</h3><ul class=\"list-paddingleft-2\"><li><p>Region management (multi-language)</p></li><li><p>Model management (custom content model)</p></li><li><p>Model field management (custom model field)</p></li><li><p>Column management</p></li><li><p>Content management (single page content, article content, product content...custom content model)</p></li><li><p>Site configuration, company information</p></li><li><p>Custom tags (custom front-end tags)</p></li><li><p>Front-end template tags</p></li><li><p>Carousel images</p></li><li><p>Multi-condition filtering</p></li><li><p>Site map (s </p></li><li><p>Friendly links</p></li><li><p>Custom forms</p></li><li><p>Message information</p></li><li><p>Article internal links</p></li><li><p>Multi-condition search</p></li><li><p>Baidu push</p></li><li><p>Content permissions</p></li><li><p>Member functions (login, register, retrieve password, change password, balance, points, log out)</p></li><li><p>Member fields</p></li><li><p>Member level (set column and content browsing permissions)</p></li><li><p>Article comments (reply, review)</p></li><li><p>My comments</p></li></ul>', 'bc', '', '', 'IntroductionBadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comme...', 3, '1', '0', '0', '0', 38, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:24:03', '4', '', '', '23', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (231, 'oe', '114', '', 'badoucms-Funktionsliste', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '', '', '<p><br /></p><h3>Einführung</h3><p>BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu Push, Karussell, Filterung mit mehreren Bedingungen, Sitemap usw. </p><h3>Funktionsliste</h3><ul class=\"list-paddingleft-2\"><li><p>Regionsverwaltung (mehrsprachig)</p></li><li><p>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Modellfeldverwaltung (benutzerdefiniertes Modellfeld)</p></li><li><p>Spaltenverwaltung</p></li><li><p>Inhaltsverwaltung (Einzelseiteninhalt, Artikelinhalt, Produktinhalt ... benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Site-Konfiguration, Unternehmensinformationen</p></li><li><p>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</p></li><li><p>Front-End-Vorlagen-Tags</p></li><li><p>Karussellbilder</p></li><li><p>Mehrere Bedingungen Filterung</p></li><li><p>Sitemap (s </p></li><li><p>Freundliche Links</p></li><li><p>Benutzerdefinierte Formulare</p></li><li><p>Nachrichteninformationen</p></li><li><p>Interne Artikellinks</p></li><li><p>Suche mit mehreren Bedingungen</p></li><li><p>Baidu Push</p></li><li><p>Inhaltsberechtigungen</p></li><li><p>Mitgliederfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</p></li><li><p>Mitgliederfelder</p></li><li><p>Mitgliedsebene (Berechtigungen zum Durchsuchen von Spalten und Inhalten festlegen)</p></li><li><p>Artikelkommentare (Antworten, Überprüfen)</p></li><li><p>Meine Kommentare</p></li></ul>', 'bc', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsf...', 3, '1', '0', '0', '0', 38, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:24:03', '4', '', '', '23', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (232, 'jp', '115', '', 'badoucms 機能リスト', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '', '', '<p><br /></p><h3>はじめに</h3><p>BadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多条件フィルタリング、サイトマップなどをサポートしています。</p><h3>機能一覧</h3><ul class=\"list-paddingleft-2\"><li><p>地域管理（多言語）</p></li><li><p>モデル管理（カスタムコンテンツモデル）</p></li><li><p>モデルフィールド管理（カスタムモデルフィールド）</p></li><li><p>列管理</p></li><li><p>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</p></li><li><p>サイト構成、会社情報</p></li><li><p>カスタムタグ（カスタムフロントエンドタグ）</p></li><li><p>フロントエンドテンプレートタグ</p></li><li><p>カルーセル画像</p></li><li><p>多条件フィルタリング</p></li><li><p>サイトマップ（s </p></li><li><p>フレンドリーリンク</p></li><li><p>カスタムフォーム</p></li><li><p>メッセージ情報</p></li><li><p>記事内部リンク</p></li><li><p>複数条件検索</p></li><li><p>Baiduプッシュ</p></li><li><p>コンテンツ権限</p></li><li><p>メンバー機能（ログイン、登録、パスワードの取得、パスワードの変更、残高、ポイント、ログアウト）</p></li><li><p>メンバーフィールド</p></li><li><p>メンバーレベル（列とコンテンツの閲覧権限の設定）</p></li><li><p>記事コメント（返信、レビュー）</p></li><li><p>私のコメント</p></li></ul>', 'bc', '', '', 'はじめにBadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多...', 3, '1', '0', '0', '0', 38, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:24:03', '4', '', '', '23', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (235, 'jp', '106', '', '配達時間はどれくらいですか？', '', '', '', '', '', '', '2025-10-24 14:47:48', '', '', '', 'サンプルのリードタイムは約7日間です。量産リードタイムは、ご入金確認後20～30日です。リードタイムは、ご入金確認後、製品の最終承認をいただいた時点から開始されます。リードタイムがお客様のご都合に合わない場合は、販売時にご要望をご確認ください。いかなる場合でも、お客様のご要望にお応えできるよう最善を尽くし、ほとんどの場合、ご対応可能です。', '', '', '', 'サンプルのリードタイムは約7日間です。量産リードタイムは、ご入金確認後20～30日です。リードタイムは、ご入金確認後、製品の最終承認をいただいた時点から開始されます。リードタイムがお客様のご都合に合わない場合は、販売時にご要望をご確認ください。いかなる場合でも、お客様のご要望にお応えできるよう最善を尽くし...', 0, '1', '0', '0', '0', 0, 0, 0, 'admin', 'admin', '2025-10-24 14:48:34', '2025-10-27 17:25:03', '', '', '', '3', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (236, 'en', '116', '', 'Platform Operation', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/6941ed287ece8bba00ad53273beadf45.jpeg', '', '', '<p><strong>Job Responsibilities:</strong></p><p>1. Responsible for the business support work of platform operations and ensure the stable development of platform business;</p><p>2. Participate in and optimize the department\'s business operation process to ensure team collaboration;</p><p>3. Provide platform business consulting services to users;</p><p>4. Accept customer complaints and resolve them within the scope of authorization;</p><p>5. Record and edit videos of online activities, discover excellent works, and simply edit and process background information;</p><p>6. Cooperate with other departments of the company. </p><p><br /></p><p><strong>Job Requirements:</strong></p><p>1. College degree or above, love the Internet industry;</p><p>2. Strong sense of responsibility, hardworking, positive and cheerful;</p><p>3. Good image, eloquent, standard Mandarin;</p><p>4. Proficient in computer, frequent Internet access, and able to use office and other related office software;</p><p>5. Able to adapt to day and night shift work;</p><p>Note: Based on personal ability and expertise, the company will provide more development and promotion space.</p><p><br /></p><p><strong>Work Address:</strong>                        </p><h2>Beiyuan Road, Chaoyang District, Beijing</h2>', '', '', '', 'Job Responsibilities:1. Responsible for the business support work of platform operations and ensure the stable development of platform business;2. Participate in and optimize the department&#039;s business operation process to ensure team collaboration;3. Provide platform business consulting services to ...', 255, '1', '0', '0', '0', 5, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:25:25', '4', '', '', '24', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (14, 'cn', '8', '', '常州xxx钢铁企业官网', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/11955a54eb5585a3bb436a69ffde7cc1.jpeg', '', '', '<p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul><li>区域管理（多语言）</li><li>模型管理（自定义内容模型）</li><li>模型字段管理（自定义模型字段）</li><li>栏目管理</li><li>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</li><li>站点配置、公司信息</li><li>定制标签（自定义前台标签）</li><li>前台模版标签</li><li>轮播图片</li><li>多条件筛选</li><li>网站地图（sitemap）</li><li>友情链接</li><li>自定义表单</li><li>留言信息</li><li>文章内链</li><li>多条件搜索</li><li>百度推送</li><li>内容权限</li><li>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</li><li>会员字段</li><li>会员等级(设置栏目与内容浏览权限)</li><li>文章评论(回复、审核)</li><li>我的评论</li></ul>', '', '', '', 'BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模型字...', 252, '1', '0', '0', '0', 27, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-31 15:01:33', '4', '', '', '35', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (50, 'cn', '8', '', '无锡xxx建筑公司官网1', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/e011298e4ec8e8e20fe32e14431f9763.jpeg', '/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg,/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg', '', '<p>\n	BadouCMS 最好 基于 Layui + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。\n</p>\n<h3>\n	功能列表111\n</h3>\n<ul>\n	<li>\n		区域管理（多语言）\n	</li>\n	<li>\n		模型管理（自定义内容模型）\n	</li>\n	<li>\n		模型字段管理（自定义模型字段）\n	</li>\n	<li>\n		栏目管理\n	</li>\n	<li>\n		内容管理（单页内容、文章内容、产品内容...自定义内容模型）\n	</li>\n	<li>\n		站点配置、公司信息\n	</li>\n	<li>\n		定制标签（自定义前台标签）\n	</li>\n	<li>\n		前台模版标签\n	</li>\n	<li>\n		轮播图片\n	</li>\n	<li>\n		多条件筛选\n	</li>\n	<li>\n		网站地图（sitemap）\n	</li>\n	<li>\n		友情链接\n	</li>\n	<li>\n		自定义表单\n	</li>\n	<li>\n		留言信息\n	</li>\n	<li>\n		文章内链\n	</li>\n	<li>\n		多条件搜索\n	</li>\n	<li>\n		百度推送\n	</li>\n	<li>\n		内容权限\n	</li>\n	<li>\n		会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)\n	</li>\n	<li>\n		会员字段\n	</li>\n	<li>\n		会员等级(设置栏目与内容浏览权限)\n	</li>\n	<li>\n		文章评论(回复、审核)\n	</li>\n	<li>\n		我的评论\n	</li>\n</ul>', '', '', '', 'BadouCMS 最好 基于 Layui + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表111区域管理（多语言）模型管理（自定义内容模型）...', 251, '1', '0', '0', '0', 43, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-27 17:39:25', '4', '', '', '34', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (28, 'zh-cn', '29', '', 'accesser', '#333333', '', '', 'Admin', '本站', '', '2024-09-14 21:53:08', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 0, 0, 0, 'Admin', 'Admin', '2024-11-24 11:01:31', '2024-11-24 11:01:31', '4', '0', '', '', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (29, 'zh-cn', '30', '', '单页测试1', '#333333', '', '', 'Admin', '本站', '', '2024-09-14 21:54:08', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 0, 0, 0, 'Admin', 'Admin', '2024-11-24 11:01:31', '2024-11-24 11:01:31', '4', '0', '', '', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (225, 'oe', '114', '', 'badoucms Website-Management-System basierend auf thinkphp8+vue3', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/d5b47d3f753508adbb095aa1883b44b6.jpg', '', '', '<p><br /></p><h3>Einführung</h3><p>BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu Push, Karussell, Filterung mit mehreren Bedingungen, Sitemap usw. </p><p><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><h3>Funktionsliste</h3><ul class=\"list-paddingleft-2\"><li><p>Regionsverwaltung (mehrsprachig)</p></li><li><p>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Modellfeldverwaltung (benutzerdefiniertes Modell Feld)</p></li><li><p>Spaltenverwaltung</p></li><li><p>Inhaltsverwaltung (Einzelseiteninhalte, Artikelinhalte, Produktinhalte ... benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Site-Konfiguration, Unternehmensinformationen</p></li><li><p>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</p></li><li><p>Front-End-Vorlagen-Tags</p></li><li><p>Karussellbilder</p></li><li><p>Filterung mit mehreren Bedingungen</p></li><li><p>Sitemap (s </p></li><li><p>Freundliche Links</p></li><li><p>Benutzerdefinierte Formulare</p></li><li><p>Nachrichteninformationen</p></li><li><p>Interne Artikellinks</p></li><li><p>Suche mit mehreren Bedingungen</p></li><li><p>Baidu Push</p></li><li><p>Inhaltsberechtigungen</p></li><li><p>Mitgliederfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</p></li><li><p>Mitgliederfelder</p></li><li><p>Mitgliedsebene (Berechtigungen zum Durchsuchen von Spalten und Inhalten festlegen)</p></li><li><p>Artikelkommentare (Antworten, Überprüfen)</p></li><li><p>Meine Kommentare</p></li></ul>', 'cms', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsf...', 2, '1', '0', '0', '0', 19, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:43', '4', '', '', '21', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (226, 'jp', '115', '', 'thinkphp8+vue3 をベースにした badoucms ウェブサイト管理システム', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/d5b47d3f753508adbb095aa1883b44b6.jpg', '', '', '<p><br /></p><h3>はじめに</h3><p>BadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多条件フィルタリング、サイトマップなどをサポートしています。</p><p><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><h3>機能一覧</h3><ul class=\"list-paddingleft-2\"><li><p>リージョン管理（多言語）</p></li><li><p>モデル管理（カスタムコンテンツモデル）</p></li><li><p>モデルフィールド管理（カスタムモデルフィールド）</p></li><li><p>列管理</p></li><li><p>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、製品コンテンツ...カスタムコンテンツモデル）</p></li><li><p>サイト構成、会社情報</p></li><li><p>カスタムタグ（カスタムフロントエンドタグ）</p></li><li><p>フロントエンドテンプレートタグ</p></li><li><p>カルーセル画像</p></li><li><p>複数条件フィルタリング</p></li><li><p>サイトマップ（</p></li><li><p>フレンドリーリンク</p></li><li><p>カスタムフォーム</p></li><li><p>メッセージ情報</p></li><li><p>記事内部リンク</p></li><li><p>複数条件検索</p></li><li><p>Baiduプッシュ</p></li><li><p>コンテンツ権限</p></li><li><p>会員機能（ログイン、登録、パスワード取得、パスワード変更、残高、ポイント、ログ</p></li><li><p>メンバーフィールド</p></li><li><p>メンバーレベル（列とコンテンツの閲覧権限の設定）</p></li><li><p>記事コメント（返信、レビュー）</p></li><li><p>私のコメント</p></li></ul>', 'cms', '', '', 'はじめにBadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多...', 2, '1', '0', '0', '0', 19, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:43', '4', '', '', '21', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (19, 'cn', '10', '', 'test', '#333333', '', '', '超级管理员', '本站', '', '2023-01-05 15:46:46', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 294, 0, 0, 'admin', 'admin', '2023-01-05 15:46:46', '2025-10-27 17:40:13', '4', '', '', '2', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (153, 'jp', '87', '', '公司简介', '#333333', '', '', 'Admin', '本站', '', '2025-10-24 22:20:22', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 6, 0, 0, 'Admin', 'Admin', '2025-10-24 22:20:22', '2025-10-26 21:15:15', '4', '0', '', '', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (60, 'cn', '9', '', '淘宝运营', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/bce882d6ddebc9f7e91248392e891fe0.jpeg', '/storage/default/20241126/teams4f3c94f4696e55452f157173f340e2d321252398a.jpeg,/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg', '', '<p><strong>岗位职责：</strong></p><p style=\"text-align:center;\"><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><p><br /></p><p>1、 负责平台运营的业务支撑工作，保证平台业务稳定发展；</p><p>2、 参与和优化部门业务操作流程，保证团队协同工作；</p><p>3、 为用户提供平台业务咨询服务；</p><p>4、 受理客户投诉，在授权范围内予以解决；</p><p>5、 网络活动视频录像与剪辑，挖掘优秀作品,后台信息简单编辑处理；</p><p>6、 与公司其他部门配合工作。</p><p style=\"text-align:center;\"><img src=\"/storage/default/20241130/logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" alt=\"logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" /></p><p><strong>任职要求：</strong></p><p>1、 专科及以上学历，热爱互联网行业；</p><p>2、 较强的工作责任心，踏实勤恳，积极向上，性格开朗；</p><p>3、 形象佳，口齿伶俐，普通话标准；</p><p>4、 熟练使用电脑，经常上网，会使用office等相关办公软件；</p><p>5、 能适应白班、夜班倒班工作制；</p><p>注：根据个人能力和特长，公司给予更多的发展及晋升空间。</p><p><br /></p><p><strong>工作地址：</strong>                        </p><h2>北京市朝阳区北苑路</h2>', '', '', '', '岗位职责：1、 负责平台运营的业务支撑工作，保证平台业务稳定发展；2、 参与和优化部门业务操作流程，保证团队协同工作；3、 为用户提供平台业务咨询服务；4、 受理客户投诉，在授权范围内予以解决；5、 网络活动视频录像与剪辑，挖掘优秀作品,后台信息简单编辑处理；6、 与公司其他部门配合工作。任职要求：1、 专科及以上...', 255, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-31 15:01:24', '4', '', '', '25', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (61, 'cn', '33', '', 'badoucms 正式上线1.0.0 版本', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/d04eedf5fa381fbf8779592ad3783375.jpeg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p><img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" /></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul class=\"list-paddingleft-2\"><li><p>区域管理（多语言）</p></li><li><p>模型管理（自定义内容模型）</p></li><li><p>模型字段管理（自定义模型字段）</p></li><li><p>栏目管理</p></li><li><p>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p>站点配置、公司信息</p></li><li><p>定制标签（自定义前台标签）</p></li><li><p>前台模版标签</p></li><li><p>轮播图片</p></li><li><p>多条件筛选</p></li><li><p>网站地图（sitemap）</p></li><li><p>友情链接</p></li><li><p>自定义表单</p></li><li><p>留言信息</p></li><li><p>文章内链</p></li><li><p>多条件搜索</p></li><li><p>百度推送</p></li><li><p>内容权限</p></li><li><p>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p>会员字段</p></li><li><p>会员等级(设置栏目与内容浏览权限)</p></li><li><p>文章评论(回复、审核)</p></li><li><p>我的评论</p></li></ul>', 'badoucms,a,b', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模...', 11, '1', '0', '0', '0', 36, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:54', '4', '', '请先充值', '22', '');
