INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (52, 'cn', '8', '', '南京xxx建筑公司官网', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/cd555fd12db37e3a91e97c17b13db4fa.jpeg', '', '', '<p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul><li>区域管理（多语言）</li><li>模型管理（自定义内容模型）</li><li>模型字段管理（自定义模型字段）</li><li>栏目管理</li><li>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</li><li>站点配置、公司信息</li><li>定制标签（自定义前台标签）</li><li>前台模版标签</li><li>轮播图片</li><li>多条件筛选</li><li>网站地图（sitemap）</li><li>友情链接</li><li>自定义表单</li><li>留言信息</li><li>文章内链</li><li>多条件搜索</li><li>百度推送</li><li>内容权限</li><li>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</li><li>会员字段</li><li>会员等级(设置栏目与内容浏览权限)</li><li>文章评论(回复、审核)</li><li>我的评论</li></ul>', '', '', '', 'BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模型字...', 254, '1', '0', '0', '0', 38, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-27 17:32:58', '4', '', '', '32', '');
