INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (65, 'cn', '33', '', 'badoucms 模板标签', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul><li> 区域管理（多语言）</li><li> 模型管理（自定义内容模型）</li><li> 模型字段管理（自定义模型字段）</li><li> 栏目管理</li><li> 内容管理（单页内容、文章内容、产品内容...自定义内容模型）</li><li> 站点配置、公司信息</li><li> 定制标签（自定义前台标签）</li><li> 前台模版标签</li><li> 轮播图片</li><li> 多条件筛选</li><li> 网站地图（sitemap）</li><li> 友情链接</li><li> 自定义表单</li><li> 留言信息</li><li> 文章内链</li><li> 多条件搜索</li><li> 百度推送</li><li> 内容权限</li><li> 会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</li><li> 会员字段</li><li> 会员等级(设置栏目与内容浏览权限)</li><li> 文章评论(回复、审核)</li><li> 我的评论</li></ul>', '', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表 区域管理（多语言） 模型管理（自定义内容模型） 模型字段管理（自定义...', 4, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:31', '4', '', '', '20', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (66, 'cn', '33', '', 'BadouCMS快速入门', '', '', '', '', '', '', '2024-11-15 08:15:20', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>图片缩放函数：resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>参数：$src_image=源图片路径 （必填）</p><p>$max_width=缩放后的宽度</p><p>$max_height=缩放后的高度</p><p>$img_quality=图片质量</p><p>在标签中使用：<code>{$item.ico|resize_img=\'10\',\'10\'}</code></p>', 'wy', '', '', '测试新闻1', 255, '1', '0', '0', '0', 58, 0, 0, 'Admin', 'admin', '2024-11-15 08:18:25', '2025-10-27 17:23:20', '4', '', '', '19', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (223, 'jp', '115', '', 'badoucms テンプレートタグ', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>はじめに</h3><p>BadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像、多条件フィルタリング、サイトマップなどをサポートしています。</p><h3>機能一覧</h3><ul><li>地域管理（多言語）</li><li>モデル管理（カスタムコンテンツモデル）</li><li>モデルフィールド管理（カスタムモデルフィールド）</li><li>列管理</li><li>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</li><li>サイト構成、会社情報</li><li>カスタムタグ（カスタムフロントエンドタグ）</li><li>フロントエンドテンプレートタグ</li><li>カルーセル画像</li><li>多条件フィルタリング</li><li>ウェブサイトマップ（サイトマップ）</li><li>フレンドリーリンク</li><li>カスタムフォーム</li><li>メッセージ情報</li><li>記事内部リンク</li><li>多条件検索</li><li>Baidu Push</li><li>コンテンツ権限</li><li>会員機能（ログイン、登録、パスワード取得、パスワード変更、残高、ポイント、ログアウト）</li><li>会員フィールド</li><li>会員レベル（列とコンテンツ閲覧権限の設定）</li><li>記事コメント（返信、レビュー）</li><li>私のコメント</li></ul>', '', '', '', 'はじめにBadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像...', 4, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:31', '4', '', '', '20', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (212, 'en', '110', '110,113', 'badoucms website management system based on thinkphp8+vue3', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/d5b47d3f753508adbb095aa1883b44b6.jpg', '', '', '<p><br /></p><h3>Introduction</h3><p>BadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel, multi-condition filtering, site map, etc. </p><p><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><h3>Feature List</h3><ul class=\"list-paddingleft-2\"><li><p>Region management (multi-language)</p></li><li><p>Model management (custom content model)</p></li><li><p>Model field management (custom model field)</p></li><li><p>Column management</p></li><li><p>Content management (single page content, article content, product content...custom content model)</p></li><li><p>Site configuration, company information</p></li><li><p>Custom tags (custom front-end tags)</p></li><li><p>Front-end template tags</p></li><li><p>Carousel images</p></li><li><p>Multi-condition filtering</p></li><li><p>Site map (s </p></li><li><p>Friendly links</p></li><li><p>Custom forms</p></li><li><p>Message information</p></li><li><p>Article internal links</p></li><li><p>Multi-condition search</p></li><li><p>Baidu push</p></li><li><p>Content permissions</p></li><li><p>Member functions (login, register, retrieve password, change password, balance, points, log out)</p></li><li><p>Member fields</p></li><li><p>Member level (set column and content browsing permissions)</p></li><li><p>Article comments (reply, review)</p></li><li><p>My comments</p></li></ul>', 'cms', '', '', 'IntroductionBadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comme...', 2, '1', '0', '0', '0', 16, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:22:35', '4', '', '', '17', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (213, 'oe', '111', '111,114', 'badoucms Website-Management-System basierend auf thinkphp8+vue3', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/d5b47d3f753508adbb095aa1883b44b6.jpg', '', '', '<p><br /></p><h3>Einführung</h3><p>BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu Push, Karussell, Filterung mit mehreren Bedingungen, Sitemap usw. </p><p><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><h3>Funktionsliste</h3><ul class=\"list-paddingleft-2\"><li><p>Regionsverwaltung (mehrsprachig)</p></li><li><p>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Modellfeldverwaltung (benutzerdefiniertes Modell Feld)</p></li><li><p>Spaltenverwaltung</p></li><li><p>Inhaltsverwaltung (Einzelseiteninhalte, Artikelinhalte, Produktinhalte ... benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Site-Konfiguration, Unternehmensinformationen</p></li><li><p>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</p></li><li><p>Front-End-Vorlagen-Tags</p></li><li><p>Karussellbilder</p></li><li><p>Filterung mit mehreren Bedingungen</p></li><li><p>Sitemap (s </p></li><li><p>Freundliche Links</p></li><li><p>Benutzerdefinierte Formulare</p></li><li><p>Nachrichteninformationen</p></li><li><p>Interne Artikellinks</p></li><li><p>Suche mit mehreren Bedingungen</p></li><li><p>Baidu Push</p></li><li><p>Inhaltsberechtigungen</p></li><li><p>Mitgliederfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</p></li><li><p>Mitgliederfelder</p></li><li><p>Mitgliedsebene (Berechtigungen zum Durchsuchen von Spalten und Inhalten festlegen)</p></li><li><p>Artikelkommentare (Antworten, Überprüfen)</p></li><li><p>Meine Kommentare</p></li></ul>', 'cms', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsf...', 2, '1', '0', '0', '0', 16, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:22:35', '4', '', '', '17', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (214, 'jp', '112', '112,115', 'thinkphp8+vue3 をベースにした badoucms ウェブサイト管理システム', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/d5b47d3f753508adbb095aa1883b44b6.jpg', '', '', '<p><br /></p><h3>はじめに</h3><p>BadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多条件フィルタリング、サイトマップなどをサポートしています。</p><p><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><h3>機能一覧</h3><ul class=\"list-paddingleft-2\"><li><p>リージョン管理（多言語）</p></li><li><p>モデル管理（カスタムコンテンツモデル）</p></li><li><p>モデルフィールド管理（カスタムモデルフィールド）</p></li><li><p>列管理</p></li><li><p>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、製品コンテンツ...カスタムコンテンツモデル）</p></li><li><p>サイト構成、会社情報</p></li><li><p>カスタムタグ（カスタムフロントエンドタグ）</p></li><li><p>フロントエンドテンプレートタグ</p></li><li><p>カルーセル画像</p></li><li><p>複数条件フィルタリング</p></li><li><p>サイトマップ（</p></li><li><p>フレンドリーリンク</p></li><li><p>カスタムフォーム</p></li><li><p>メッセージ情報</p></li><li><p>記事内部リンク</p></li><li><p>複数条件検索</p></li><li><p>Baiduプッシュ</p></li><li><p>コンテンツ権限</p></li><li><p>会員機能（ログイン、登録、パスワード取得、パスワード変更、残高、ポイント、ログ</p></li><li><p>メンバーフィールド</p></li><li><p>メンバーレベル（列とコンテンツの閲覧権限の設定）</p></li><li><p>記事コメント（返信、レビュー）</p></li><li><p>私のコメント</p></li></ul>', 'cms', '', '', 'はじめにBadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多...', 2, '1', '0', '0', '0', 17, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-29 20:41:30', '4', '', '', '17', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (217, 'jp', '112', '', 'badoucms 機能リスト', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '', '', '<p><br /></p><h3>はじめに</h3><p>BadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多条件フィルタリング、サイトマップなどをサポートしています。</p><h3>機能一覧</h3><ul class=\"list-paddingleft-2\"><li><p>地域管理（多言語）</p></li><li><p>モデル管理（カスタムコンテンツモデル）</p></li><li><p>モデルフィールド管理（カスタムモデルフィールド）</p></li><li><p>列管理</p></li><li><p>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</p></li><li><p>サイト構成、会社情報</p></li><li><p>カスタムタグ（カスタムフロントエンドタグ）</p></li><li><p>フロントエンドテンプレートタグ</p></li><li><p>カルーセル画像</p></li><li><p>多条件フィルタリング</p></li><li><p>サイトマップ（s </p></li><li><p>フレンドリーリンク</p></li><li><p>カスタムフォーム</p></li><li><p>メッセージ情報</p></li><li><p>記事内部リンク</p></li><li><p>複数条件検索</p></li><li><p>Baiduプッシュ</p></li><li><p>コンテンツ権限</p></li><li><p>メンバー機能（ログイン、登録、パスワードの取得、パスワードの変更、残高、ポイント、ログアウト）</p></li><li><p>メンバーフィールド</p></li><li><p>メンバーレベル（列とコンテンツの閲覧権限の設定）</p></li><li><p>記事コメント（返信、レビュー）</p></li><li><p>私のコメント</p></li></ul>', 'bc', '', '', 'はじめにBadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多...', 3, '1', '0', '0', '0', 30, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:23:11', '4', '', '', '18', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (218, 'en', '113', '', 'BadouCMS Quick Start', '', '', '', '', '', '', '2024-11-15 08:15:20', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>Image scaling function: resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>Parameters: $src_image = source image path (required)</p><p>$max_width = width after scaling</p><p>$max_height = height after scaling</p><p>$img_quality = image quality</p><p>Use in tags: <code>{$item.ico|resize_img=\'10\',\'10\'}</code></p>', 'wy', '', '', 'Test News 1', 255, '1', '0', '0', '0', 58, 0, 0, 'Admin', 'admin', '2024-11-15 08:18:25', '2025-10-27 17:23:19', '4', '', '', '19', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (219, 'oe', '114', '', 'Erste Schritte mit BadouCMS', '', '', '', '', '', '', '2024-11-15 08:15:20', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>Bildskalierungsfunktion: resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>Parameter: $src_image = Quellbildpfad (erforderlich)</p><p>$max_width = Breite nach der Skalierung</p><p>$max_height = Höhe nach der Skalierung</p><p>$img_quality = Bildqualität</p><p>Verwendung in Tags: <code>{$item.ico|resize_img=\'10\',\'10\'}</code></p>', 'wy', '', '', 'Testnachrichten 1', 255, '1', '0', '0', '0', 58, 0, 0, 'Admin', 'admin', '2024-11-15 08:18:25', '2025-10-27 17:23:19', '4', '', '', '19', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (220, 'jp', '115', '', 'BadouCMS クイックスタート', '', '', '', '', '', '', '2024-11-15 08:15:20', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>画像拡大縮小関数: resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>パラメータ: $src_image = ソース画像のパス（必須）</p><p>$max_width = 拡大縮小後の幅</p><p>$max_height = 拡大縮小後の高さ</p><p>$img_quality = 画像の品質</p><p>タグで使用: <code>{$item.ico|resize_img=\'10\',\'10\'></code></p>', 'wy', '', '', 'テストニュース1', 255, '1', '0', '0', '0', 58, 0, 0, 'Admin', 'admin', '2024-11-15 08:18:25', '2025-10-27 17:23:19', '4', '', '', '19', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (221, 'en', '113', '', 'badoucms template tags', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>Introduction</h3><p>BadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel images, multi-condition filtering, site map, etc. </p><h3>Function List</h3><ul><li>Region Management (Multi-language)</li><li>Model Management (Custom Content Model)</li><li>Model Field Management (Custom Model Field)</li><li>Column Management</li><li>Content Management (Single Page Content, Article Content, Product Content...Custom Content Model)</li><li>Site Configuration, Company Information</li><li>Custom Tags (Custom Front-end Tags)</li><li>Front-end Template Tags</li><li>Carousel Images</li><li>Multi-condition Filtering</li><li>Website Map (sitemap)</li><li>Friendly Links</li><li>Custom Forms</li><li>Message Information</li><li>Article Internal Links</li><li>Multi-condition Search</li><li>Baidu Push</li><li>Content Permissions</li><li>Membership Functions (Login, Register, Retrieve Password, Change Password, Balance, Points, Logout)</li><li>Membership Fields</li><li> Member Level (Set columns and content browsing permissions)</li><li> Article Comments (Reply, Review)</li><li> My Comments</li></ul>', '', '', '', 'IntroductionBadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comme...', 4, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:31', '4', '', '', '20', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (222, 'oe', '114', '', 'badoucms-Vorlagen-Tags', '', '', '', '', '', '', '2024-11-15 08:13:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>Einführung</h3><p>BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu Push, Karussellbilder, Filterung mit mehreren Bedingungen, Sitemap usw. </p><h3>Funktionsliste</h3><ul><li>Regionsverwaltung (mehrsprachig)</li><li>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</li><li>Modellfeldverwaltung (benutzerdefiniertes Modellfeld)</li><li>Spaltenverwaltung</li><li>Inhaltsverwaltung (Einzelseiteninhalt, Artikelinhalt, Produktinhalt ... benutzerdefiniertes Inhaltsmodell)</li><li>Site-Konfiguration, Unternehmensinformationen</li><li>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</li><li>Front-End-Vorlagen-Tags</li><li>Karussellbilder</li><li>Filterung mit mehreren Bedingungen</li><li>Website-Karte (Sitemap)</li><li>Freundliche Links</li><li>Benutzerdefinierte Formulare</li><li>Nachrichteninformationen</li><li>Interne Artikellinks</li><li>Suche mit mehreren Bedingungen</li><li>Baidu Push</li><li>Inhaltsberechtigungen</li><li>Mitgliedschaftsfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</li><li>Mitgliedschaftsfelder</li><li> Mitgliedsebene (Spalten und Berechtigungen zum Durchsuchen von Inhalten festlegen)</li><li> Artikelkommentare (Antworten, Überprüfen)</li><li> Meine Kommentare</li></ul>', '', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsf...', 4, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2024-11-15 08:14:50', '2025-10-27 17:23:31', '4', '', '', '20', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (209, 'en', '110', '', 'badoucms template tags', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>Introduction</h3><p>BadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel images, multi-condition filtering, site map, etc. </p><h3>Function List</h3><ul><li>Region Management (Multi-language)</li><li>Model Management (Custom Content Model)</li><li>Model Field Management (Custom Model Field)</li><li>Column Management</li><li>Content Management (Single Page Content, Article Content, Product Content...Custom Content Model)</li><li>Site Configuration, Company Information</li><li>Custom Tags (Custom Front-end Tags)</li><li>Front-end Template Tags</li><li>Carousel Images</li><li>Multi-condition Filtering</li><li>Website Map (sitemap)</li><li>Friendly Links</li><li>Custom Forms</li><li>Message Information</li><li>Article Internal Links</li><li>Multi-condition Search</li><li>Baidu Push</li><li>Content Permissions</li><li>Membership Functions (Login, Register, Retrieve Password, Change Password, Balance, Points, Logout)</li><li>Membership Fields</li><li> Member Level (Set columns and content browsing permissions)</li><li> Article Comments (Reply, Review)</li><li> My Comments</li></ul>', '', '', '', 'IntroductionBadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comme...', 4, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:21:58', '4', '', '', '16', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (210, 'oe', '111', '', 'badoucms-Vorlagen-Tags', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>Einführung</h3><p>BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu-Push, Karussellbilder, Filterung mit mehreren Bedingungen, Sitemap usw. </p><h3>Funktionsliste</h3><ul><li>Regionsverwaltung (mehrsprachig)</li><li>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</li><li>Modellfeldverwaltung (benutzerdefiniertes Modellfeld)</li><li>Spaltenverwaltung</li><li>Inhaltsverwaltung (Einzelseiteninhalt, Artikelinhalt, Produktinhalt ... benutzerdefiniertes Inhaltsmodell)</li><li>Site-Konfiguration, Unternehmensinformationen</li><li>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</li><li>Front-End-Vorlagen-Tags</li><li>Karussellbilder</li><li>Filterung mit mehreren Bedingungen</li><li>Website-Karte (Sitemap)</li><li>Freundliche Links</li><li>Benutzerdefinierte Formulare</li><li>Nachrichteninformationen</li><li>Interne Artikellinks</li><li>Suche mit mehreren Bedingungen</li><li>Baidu Push</li><li>Inhaltsberechtigungen</li><li>Mitgliedschaftsfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</li><li>Mitgliedschaftsfelder</li><li> Mitgliedsebene (Spalten und Berechtigungen zum Durchsuchen von Inhalten festlegen)</li><li> Artikelkommentare (Antworten, Überprüfen)</li><li> Meine Kommentare</li></ul>', '', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsf...', 4, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:21:58', '4', '', '', '16', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (211, 'jp', '112', '', 'badoucms テンプレートタグ', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>はじめに</h3><p>BadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像、多条件フィルタリング、サイトマップなどをサポートしています。</p><h3>機能一覧</h3><ul><li>地域管理（多言語）</li><li>モデル管理（カスタムコンテンツモデル）</li><li>モデルフィールド管理（カスタムモデルフィールド）</li><li>列管理</li><li>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</li><li>サイト構成、会社情報</li><li>カスタムタグ（カスタムフロントエンドタグ）</li><li>フロントエンドテンプレートタグ</li><li>カルーセル画像</li><li>多条件フィルタリング</li><li>ウェブサイトマップ（サイトマップ）</li><li>フレンドリーリンク</li><li>カスタムフォーム</li><li>メッセージ情報</li><li>記事内部リンク</li><li>多条件検索</li><li>Baidu Push</li><li>コンテンツ権限</li><li>会員機能（ログイン、登録、パスワード取得、パスワード変更、残高、ポイント、ログアウト）</li><li>会員フィールド</li><li>会員レベル（列とコンテンツ閲覧権限の設定）</li><li>記事コメント（返信、レビュー）</li><li>私のコメント</li></ul>', '', '', '', 'はじめにBadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像...', 4, '1', '0', '0', '0', 13, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:21:58', '4', '', '', '16', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (203, 'en', '110', '', 'Construction Industry Website Templates', '', '', '', 'Admin', '', '', '2025-10-24 15:17:20', '/uploads/20250622/83f70d6c57f86c51e8666b16afcb4830.jpeg', '', '', '', '', '', '', '', 252, '1', '0', '0', '0', 41, 0, 0, 'Admin', 'admin', '2025-10-24 15:17:20', '2025-10-27 17:21:34', '4', '', '', '13', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (204, 'oe', '111', '', 'Website-Vorlagen für die Baubranche', '', '', '', 'Admin', '', '', '2025-10-24 15:17:20', '/uploads/20250622/83f70d6c57f86c51e8666b16afcb4830.jpeg', '', '', '', '', '', '', '', 252, '1', '0', '0', '0', 41, 0, 0, 'Admin', 'admin', '2025-10-24 15:17:20', '2025-10-27 17:21:34', '4', '', '', '13', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (205, 'jp', '112', '', '建設業界向けウェブサイトテンプレート', '', '', '', 'Admin', '', '', '2025-10-24 15:17:20', '/uploads/20250622/83f70d6c57f86c51e8666b16afcb4830.jpeg', '', '', '', '', '', '', '', 252, '1', '0', '0', '0', 41, 0, 0, 'Admin', 'admin', '2025-10-24 15:17:20', '2025-10-27 17:21:34', '4', '', '', '13', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (206, 'en', '110', '', 'Getting Started with BadouCMS', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>Image scaling function: resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>Parameters: $src_image = source image path (required)</p><p>$max_width = width after scaling</p><p>$max_height = height after scaling</p><p>$img_quality = image quality</p><p>Use in tags: <code>{$item.ico|resize_img=\'10\',\'10\'}</code></p>', 'wy', '', '', 'Test News 1', 255, '1', '0', '0', '0', 63, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-28 15:49:22', '4', '', '', '15', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (207, 'oe', '111', '', 'Erste Schritte mit BadouCMS', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>Bildskalierungsfunktion: resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>Parameter: $src_image = Quellbildpfad (erforderlich)</p><p>$max_width = Breite nach der Skalierung</p><p>$max_height = Höhe nach der Skalierung</p><p>$img_quality = Bildqualität</p><p>Verwendung in Tags: <code>{$item.ico|resize_img=\'10\',\'10\'}</code></p>', 'wy', '', '', 'Testnachrichten 1', 255, '1', '0', '0', '0', 62, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:21:44', '4', '', '', '15', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (182, 'jp', '96', '', 'ヨガウェア韓国版ゆったりパンツ', '', '', '', '', '', '', '2025-10-26 23:06:22', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg,/uploads/20251026/d923c75065cc6ae0971b20bc8ce4cfb8.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><img src=\"/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg\" alt=\"82097961270ad5068adbb6b87f540031.jpg\"></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">紹介します</h3>\n<p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMSはThinkPHP8 + Layui + Jqueryなどの人気技術スタックをベースとしたオープンソースのwebサイト管理システムで、多言語、多モデル、多条件検索、コンテンツ権限、会員機能、記事レビュー、記事リンク、百度プッシュ、ローキャストマップ、多条件スクリーニング、webサイトマップなどをサポートしています。</p>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">機能一覧です</h3>\n<ul class=\"list-paddingleft-2\">\n <li><p style=\"padding:0px;\">地域管理(多言語)です</p></li>\n <li><p style=\"padding:0px;\">モデル管理(カスタムコンテンツモデル)です。</p></li>\n <li><p style=\"padding:0px;\">モデルフィールド管理(カスタムモデルフィールド)です。</p></li>\n <li><p style=\"padding:0px;\">コラム管理です</p></li>\n <li><p style=\"padding:0px;\">内容管理(単ページの内容、文章の内容、製品の内容…ですカスタム・コンテンツ・モデルです)</p></li>\n <li><p style=\"padding:0px;\">サイト配置、会社情報です</p></li>\n <li><p style=\"padding:0px;\">カスタムラベル(カスタムフロントラベル)です。</p></li>\n <li><p style=\"padding:0px;\">フロントの模造ラベルです</p></li>\n <li><p style=\"padding:0px;\">ラウンドキャスト画像です</p></li>\n <li><p style=\"padding:0px;\">多条件スクリーニングです</p></li>\n <li><p style=\"padding:0px;\">サイトマップです</p></li>\n <li><p style=\"padding:0px;\">友情のリンクです</p></li>\n <li><p style=\"padding:0px;\">カスタムフォーム</p></li>\n <li><p style=\"padding:0px;\">メッセージを残します</p></li>\n <li><p style=\"padding:0px;\">記事のリンクです</p></li>\n <li><p style=\"padding:0px;\">多条件検索です</p></li>\n <li><p style=\"padding:0px;\">コンテンツ権限です</p></li>\n <li><p style=\"padding:0px;\">会員機能(ログイン、登録、パスワードの返却、パスワードの変更、残高、ポイント、脱退)です。</p></li>\n <li><p style=\"padding:0px;\">会員フィールドです</p></li>\n <li><p style=\"padding:0px;\">メンバーシップレベル(コラムやコンテンツの閲覧権限を設定します)</p></li>\n <li><p style=\"padding:0px;\">記事のレビュー(返信、レビュー)です。</p></li>\n <li><p style=\"padding:0px;\">私のコメントです</p></li>\n</ul>\n<p><br></p>', '', '', '', 'BadouCMSはThinkPHP8 + Layui + Jqueryなどの人気技術スタックをベースにしたオープンソースのサイト管理システムで、多言語、多モデル、多条件検索、コンテンツ権限、会員機能、記事レビュー、記事リンク、百度プッシュ、ルーキャストマップ、多条件スクリーニング、サイトマップなどをサポートしています。機能リスト領域...', 0, '1', '0', '0', '0', 0, 0, 0, 'admin', 'admin', '2025-10-26 23:08:56', '2025-11-04 09:15:36', '', '', '', '11', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (183, 'cn', '7', '', '女生西装领黑白拼接七分袖收腰包臀连衣裙', '', '', '', '', '', '', '2025-10-26 23:13:06', '/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">介绍</h3><p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS 基于 ThinkPHP8 + Layui + Jquery 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">功能列表</h3><ul class=\"list-paddingleft-2\"><li><p style=\"padding:0px;\">区域管理（多语言）</p></li><li><p style=\"padding:0px;\">模型管理（自定义内容模型）</p></li><li><p style=\"padding:0px;\">模型字段管理（自定义模型字段）</p></li><li><p style=\"padding:0px;\">栏目管理</p></li><li><p style=\"padding:0px;\">内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p style=\"padding:0px;\">站点配置、公司信息</p></li><li><p style=\"padding:0px;\">定制标签（自定义前台标签）</p></li><li><p style=\"padding:0px;\">前台模版标签</p></li><li><p style=\"padding:0px;\">轮播图片</p></li><li><p style=\"padding:0px;\">多条件筛选</p></li><li><p style=\"padding:0px;\">网站地图（sitemap）</p></li><li><p style=\"padding:0px;\">友情链接</p></li><li><p style=\"padding:0px;\">自定义表单</p></li><li><p style=\"padding:0px;\">留言信息</p></li><li><p style=\"padding:0px;\">文章内链</p></li><li><p style=\"padding:0px;\">多条件搜索</p></li><li><p style=\"padding:0px;\">内容权限</p></li><li><p style=\"padding:0px;\">会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p style=\"padding:0px;\">会员字段</p></li><li><p style=\"padding:0px;\">会员等级(设置栏目与内容浏览权限)</p></li><li><p style=\"padding:0px;\">文章评论(回复、审核)</p></li><li><p style=\"padding:0px;\">我的评论</p></li></ul><p><img src=\"/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg\" alt=\"f8b41f2de9b3394d6e107427e27287dd.jpg\" /></p>', '', '', '', '介绍BadouCMS 基于 ThinkPHP8 + Layui + Jquery 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模型字段）栏目管理内容管理（单页内容、...', 0, '1', '0', '0', '0', 11, 0, 0, 'admin', 'admin', '2025-10-26 23:14:11', '2025-11-04 09:16:06', '', '', '', '12', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (184, 'en', '94', '', 'Women\'s black and white patchwork three-quarter sleeve fitted waist bodycon dress with suit collar', '', '', '', '', '', '', '2025-10-26 23:13:06', '/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Introduction</h3><p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS is an open-source website management system based on popular technology stacks such as ThinkPHP8 + Layui + jQuery. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel images, multi-condition filtering, site map, etc.</p> </p><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Function List</h3><ul class=\"list-paddingleft-2\"><li><p style=\"padding:0px;\">Region Management (Multilingual)</p></li><li><p style=\"padding:0px;\">Model Management (Custom Content Model)</p></li><li><p style=\"padding:0px;\">Model Field Management (Custom Model Field)</p></li><li><p style=\"padding:0px;\">Category Management</p></li><li><p style=\"padding:0px;\">Content Management (Single Page Content, Article Content, Product Content...Custom Content Model)</p></li><li><p style=\"padding:0px;\">Site Configuration, Company Information</p></li><li><p style=\"padding:0px;\">Custom Tags (Custom Front-End Tags)</p></li><li><p Front-end template tags</p></li><li><p style=\"padding:0px;\">Carousel images</p></li><li><p style=\"padding:0px;\">Multi-condition filtering</p></li><li><p style=\"padding:0px;\">Sitemap</p></li><li><p style=\"padding:0px;\">Friendly links</p></li><li><p style=\"padding:0px;\">Custom forms</p></li><li><p style=\"padding:0px;\">Message information</p></li><li><p style=\"padding:0px;\">Article internal links</p></li><li><p style=\"padding:0px;\">Multi-condition search</p></li><li><p style=\"padding:0px;\">Content permissions</p></li><li><p style=\"padding:0px;\">Member functions (login, registration, password retrieval, password modification, balance, points, logout)</p></li><li><p Member Fields</p></li><li><p style=\"padding:0px;\">Member Level (Setting Category and Content Browsing Permissions)</p></li><li><p style=\"padding:0px;\">Article Comments (Replies, Approvals)</p></li><li><p style=\"padding:0px;\">My Comments</p></li></ul><p><img src=\"/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg\" alt=\"f8b41f2de9b3394d6e107427e27287dd.jpg\" /></p>', '', '', '', 'IntroductionBadouCMS is an open-source website management system based on popular technology stacks such as ThinkPHP8 + Layui + jQuery. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu ...', 0, '1', '0', '0', '0', 7, 0, 0, 'admin', 'admin', '2025-10-26 23:14:12', '2025-11-04 08:29:16', '', '', '', '12', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (185, 'oe', '95', '', 'Schwarzes und weißes Patchwork-Kleid für Damen mit Dreiviertelärmeln, taillierter Passform und An...', '', '', '', '', '', '', '2025-10-26 23:13:06', '/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Einführung</h3><p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS ist ein Open-Source-Website-Managementsystem, das auf beliebten Technologie-Stacks wie ThinkPHP8 + Layui + jQuery basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, die Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu Push, Karussellbilder, Filterung mit mehreren Bedingungen, Sitemap usw.</p></p><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Funktionsliste</h3><ul class=\"list-paddingleft-2\"><li><p style=\"padding:0px;\">Regionsverwaltung (Mehrsprachig)</p></li><li><p style=\"padding:0px;\">Modellverwaltung (Benutzerdefiniertes Inhaltsmodell)</p></li><li><p style=\"padding:0px;\">Modellfeldverwaltung (Benutzerdefiniertes Modellfeld)</p></li><li><p style=\"padding:0px;\">Kategorieverwaltung</p></li><li><p style=\"padding:0px;\">Inhaltsverwaltung (Einzelseite) Inhalte, Artikelinhalte, Produktinhalte... Benutzerdefiniertes Inhaltsmodell)</p></li><li><p style=\"padding:0px;\">Website-Konfiguration, Unternehmensinformationen</p></li><li><p style=\"padding:0px;\">Benutzerdefinierte Tags (Benutzerdefinierte Front-End-Tags)</p></li><li><p Front-End-Template-Tags</p></li><li><p style=\"padding:0px;\">Karussellbilder</p></li><li><p style=\"padding:0px;\">Filterung mit mehreren Bedingungen</p></li><li><p style=\"padding:0px;\">Sitemap</p></li><li><p style=\"padding:0px;\">Benutzerfreundliche Links</p></li><li><p style=\"padding:0px;\">Benutzerdefinierte Formulare</p></li><li><p style=\"padding:0px;\">Nachrichteninformationen</p></li><li><p style=\"padding:0px;\">Interne Artikellinks</p></li><li><p Suche mit mehreren Bedingungen</p></li><li><p style=\"padding:0px;\">Inhaltsberechtigungen</p></li><li><p style=\"padding:0px;\">Mitgliederfunktionen (Anmeldung, Registrierung, Passwortwiederherstellung, Passwortänderung, Guthaben, Punkte, Abmeldung)</p></li><li><p Mitgliederfelder</p></li><li><p style=\"padding:0px;\">Mitgliederstufe (Einstellung von Kategorie- und Inhaltsbrowsing-Berechtigungen)</p></li><li><p style=\"padding:0px;\">Artikelkommentare (Antworten, Genehmigungen)</p></li><li><p style=\"padding:0px;\">Meine Kommentare</p></li></ul><p><img src=\"/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg\" alt=\"f8b41f2de9b3394d6e107427e27287dd.jpg\" /></p>', '', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf beliebten Technologie-Stacks wie ThinkPHP8 + Layui + jQuery basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, die Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, i...', 0, '1', '0', '0', '0', 4, 0, 0, 'admin', 'admin', '2025-10-26 23:14:12', '2025-11-04 09:16:01', '', '', '', '12', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (186, 'jp', '96', '', 'レディース ブラック＆ホワイト パッチワーク 七分袖 ウエストフィット ボディコン ドレス スーツカラー', '', '', '', '', '', '', '2025-10-26 23:13:06', '/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">はじめに</h3><p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS は、ThinkPHP8 + Layui + jQuery などの一般的なテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像、多条件フィルタリング、サイトマップなどをサポートしています。</p> </p><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">機能一覧</h3><ul class=\"list-paddingleft-2\"><li><p style=\"padding:0px;\">地域管理（多言語）</p></li><li><p style=\"padding:0px;\">モデル管理（カスタムコンテンツモデル）</p></li><li><p style=\"padding:0px;\">モデルフィールド管理（カスタムモデルフィールド）</p></li><li><p style=\"padding:0px;\">カテゴリー管理</p></li><li><p style=\"padding:0px;\">コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</p></li><li><p style=\"padding:0px;\">サイト構成、会社情報</p></li><li><p style=\"padding:0px;\">カスタムタグ（カスタムフロントエンドタグ）</p></li><li><p フロントエンドテンプレートタグ</p></li><li><p style=\"padding:0px;\">カルーセル画像</p></li><li><p style=\"padding:0px;\">複数条件フィルタリング</p></li><li><p style=\"padding:0px;\">サイトマップ</p></li><li><p style=\"padding:0px;\">フレンドリーリンク</p></li><li><p style=\"padding:0px;\">カスタムフォーム</p></li><li><p style=\"padding:0px;\">メッセージ情報</p></li><li><p style=\"padding:0px;\">記事内部リンク</p></li><li><p style=\"padding:0px;\">複数条件検索</p></li><li><p style=\"padding:0px;\">コンテンツの権限</p></li><li><p style=\"padding:0px;\">メンバー機能（ログイン、登録、パスワード取得、パスワード変更、残高、ポイント、ログアウト）</p></li><li><p メンバーフィールド</p></li><li><p style=\"padding:0px;\">メンバーレベル（カテゴリとコンテンツの閲覧権限の設定）</p></li><li><p style=\"padding:0px;\">記事コメント（返信、承認）</p></li><li><p style=\"padding:0px;\">私のコメント</p></li></ul><p><img src=\"/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg\" alt=\"f8b41f2de9b3394d6e107427e27287dd.jpg\" </p>', '', '', '', 'はじめにBadouCMS は、ThinkPHP8 + Layui + jQuery などの一般的なテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル画像、多条件フィルタリング、サイトマッ...', 0, '1', '0', '0', '0', 4, 0, 0, 'admin', 'admin', '2025-10-26 23:14:13', '2025-11-04 08:29:31', '', '', '', '12', '');
