INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (175, 'cn', '100', '', '西装领黑白拼接七分袖收腰包臀连衣裙', '', '', '', '', '', '', '2025-10-26 22:57:15', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">介绍</h3><p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS 基于 ThinkPHP8 + Layui + Jquery 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">功能列表</h3><ul class=\"list-paddingleft-2\"><li><p style=\"padding:0px;\">区域管理（多语言）</p></li><li><p style=\"padding:0px;\">模型管理（自定义内容模型）</p></li><li><p style=\"padding:0px;\">模型字段管理（自定义模型字段）</p></li><li><p style=\"padding:0px;\">栏目管理</p></li><li><p style=\"padding:0px;\">内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p style=\"padding:0px;\">站点配置、公司信息</p></li><li><p style=\"padding:0px;\">定制标签（自定义前台标签）</p></li><li><p style=\"padding:0px;\">前台模版标签</p></li><li><p style=\"padding:0px;\">轮播图片</p></li><li><p style=\"padding:0px;\">多条件筛选</p></li><li><p style=\"padding:0px;\">网站地图（sitemap）</p></li><li><p style=\"padding:0px;\">友情链接</p></li><li><p style=\"padding:0px;\">自定义表单</p></li><li><p style=\"padding:0px;\">留言信息</p></li><li><p style=\"padding:0px;\">文章内链</p></li><li><p style=\"padding:0px;\">多条件搜索</p></li><li><p style=\"padding:0px;\">内容权限</p></li><li><p style=\"padding:0px;\">会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p style=\"padding:0px;\">会员字段</p></li><li><p style=\"padding:0px;\">会员等级(设置栏目与内容浏览权限)</p></li><li><p style=\"padding:0px;\">文章评论(回复、审核)</p></li><li><p style=\"padding:0px;\">我的评论</p></li></ul><p><br /></p>', '', '', '', '介绍BadouCMS 基于 ThinkPHP8 + Layui + Jquery 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模型字段）栏目管理内容管理（单页内容、...', 0, '1', '0', '0', '0', 5, 0, 0, 'admin', 'admin', '2025-10-26 22:57:53', '2025-11-04 09:17:20', '', '', '', '10', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (176, 'en', '101', '', 'A black and white suit collar dress with three-quarter sleeves and a cinched wai...', '', '', '', '', '', '', '2025-10-26 22:57:15', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Introduction</h3>\n<p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS is an open-source website management system based on popular technology stacks such as ThinkPHP8 + Layui + Jquery. It supports multi-language, multi-model, multi-condition search, content permissions, member functions, article comments, article internal links, Baidu push, carousel images, multi-condition filtering, site maps, etc.</p>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Function list</h3>\n<ul class=\"list-paddingleft-2\">\n <li><p style=\"padding:0px;\">Regional Management (Multilingual</p></li>\n <li><p style=\"padding:0px;\">Model Management (Custom Content Model)</p></li>\n <li><p style=\"padding:0px;\">Model Field Management (Custom Model Fields)</p></li>\n <li><p style=\"padding:0px;\">Column management</p></li>\n <li><p style=\"padding:0px;\">Content management (single-page content, article content, product content...) \"Custom Content Model</p></li>\n <li><p style=\"padding:0px;\">Site configuration, company information</p></li>\n <li><p style=\"padding:0px;\">Customized tags (Custom front desk tags)</p></li>\n <li><p style=\"padding:0px;\">Front desk template tag</p></li>\n <li><p style=\"padding:0px;\">Carousel image</p></li>\n <li><p style=\"padding:0px;\">Multi-condition screening</p></li>\n <li><p style=\"padding:0px;\">sitemap</p></li>\n <li><p style=\"padding:0px;\">Friendship link</p></li>\n <li><p style=\"padding:0px;\">Custom form</p></li>\n <li><p style=\"padding:0px;\">Message information</p></li>\n <li><p style=\"padding:0px;\">Internal links within the article</p></li>\n <li><p style=\"padding:0px;\">Multi-condition search</p></li>\n <li><p style=\"padding:0px;\">Content permission</p></li>\n <li><p style=\"padding:0px;\">Member functions (login, registration, password retrieval, password modification, balance, points, logout)</p></li>\n <li><p style=\"padding:0px;\">Member field</p></li>\n <li><p style=\"padding:0px;\">Membership level (Setting column and content browsing permissions)</p></li>\n <li><p style=\"padding:0px;\">Article Comments (Replies, Reviews)</p></li>\n <li><p style=\"padding:0px;\">My comment</p></li>\n</ul>\n<p><br></p>', '', '', '', 'IntroductionBadouCMS is an open-source website management system based on popular technology stacks such as ThinkPHP8 + Layui + Jquery. It supports multi-language, multi-model, multi-condition search, content permissions, member functions, article comments, article internal links, Baidu push, carou...', 0, '1', '0', '0', '0', 9, 0, 0, 'admin', 'admin', '2025-10-26 22:57:54', '2025-11-04 09:17:23', '', '', '', '10', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (177, 'oe', '102', '', 'Anzüge stecken einen schwarz-weißen zipfel zusammen mit einem siebenfach gesä...', '', '', '', '', '', '', '2025-10-26 22:57:15', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Vorstellung.</h3>\n<p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS basiert auf einem system zur online-verwaltung Von thinkphp-8 + Layui + Jquery, das mehrsprachigkeit, vielseitige modelle, die vielseitige suche, die zugriffsfunktionen, die zugriffsfunktionen, die wortkommentare, die kette des profs, die promethie-kette, das kreuzungsdiagramm, die feldkarte der website und so weiter unterstützt.</p>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Liste der funktionen</h3>\n<ul class=\"list-paddingleft-2\">\n <li><p style=\"padding:0px;\">Regional management (mehrsprachig)</p></li>\n <li><p style=\"padding:0px;\">Klosterverwaltung (ein selbstdefiniertes inhaltsmodell)</p></li>\n <li><p style=\"padding:0px;\">Verwaltung des modellfeldes (benutzerdefiniert für modellfeld)</p></li>\n <li><p style=\"padding:0px;\">Er hält nach zielerfassung ausschau.</p></li>\n <li><p style=\"padding:0px;\">Regulierung der inhalte (seite 1, seite, text, text) Ein benutzerdefiniertes inhaltsmodell</p></li>\n <li><p style=\"padding:0px;\">Seiten einrichten, informationen zur firma</p></li>\n <li><p style=\"padding:0px;\">Standard-reiter (benutzerdefiniert als vorlage)</p></li>\n <li><p style=\"padding:0px;\">Rezeptmodell modell sind</p></li>\n <li><p style=\"padding:0px;\">Ja, das ist eine welpe.</p></li>\n <li><p style=\"padding:0px;\">Eine überprüfung vieler bedingungen</p></li>\n <li><p style=\"padding:0px;\">Eine webmap (sitemap)</p></li>\n <li><p style=\"padding:0px;\">Durch freundschaft.</p></li>\n <li><p style=\"padding:0px;\">Formulare auswerten.</p></li>\n <li><p style=\"padding:0px;\">Eine nachricht.</p></li>\n <li><p style=\"padding:0px;\">Die kette des artikels</p></li>\n <li><p style=\"padding:0px;\">Suche unter mehreren bedingungen.</p></li>\n <li><p style=\"padding:0px;\">Inhaltszugriff gewährt</p></li>\n <li><p style=\"padding:0px;\">Mitgliederfunktionen (loggen, anmelden, passwort erhalten, passwort ändern, kontostand, verdienste, ausstieg)</p></li>\n <li><p style=\"padding:0px;\">wärter</p></li>\n <li><p style=\"padding:0px;\">Stufen der mitglieder (festlegung der leiste und zugriffsrechte auf inhalt)</p></li>\n <li><p style=\"padding:0px;\">Kommentare [kommentare, überprüfung]</p></li>\n <li><p style=\"padding:0px;\">Mein urteil.</p></li>\n</ul>\n<p><br></p>', '', '', '', 'Vorstellung.BadouCMS basiert auf einem system zur online-verwaltung Von thinkphp-8 + Layui + Jquery, das mehrsprachigkeit, vielseitige modelle, die vielseitige suche, die zugriffsfunktionen, die zugriffsfunktionen, die wortkommentare, die kette des profs, die promethie-kette, das kreuzungsdiagramm,...', 0, '1', '0', '0', '0', 4, 0, 0, 'admin', 'admin', '2025-10-26 22:57:54', '2025-11-04 09:17:27', '', '', '', '10', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (178, 'jp', '103', '', '黒と白のパッチワーク七分袖ウエストポーチ入りヒップワンピースです', '', '', '', '', '', '', '2025-10-26 22:57:15', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">紹介します</h3>\n<p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMSはThinkPHP8 + Layui + Jqueryなどの人気技術スタックをベースとしたオープンソースのwebサイト管理システムで、多言語、多モデル、多条件検索、コンテンツ権限、会員機能、記事レビュー、記事リンク、百度プッシュ、ローキャストマップ、多条件スクリーニング、webサイトマップなどをサポートしています。</p>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">機能一覧です</h3>\n<ul class=\"list-paddingleft-2\">\n <li><p style=\"padding:0px;\">地域管理(多言語)です</p></li>\n <li><p style=\"padding:0px;\">モデル管理(カスタムコンテンツモデル)です。</p></li>\n <li><p style=\"padding:0px;\">モデルフィールド管理(カスタムモデルフィールド)です。</p></li>\n <li><p style=\"padding:0px;\">コラム管理です</p></li>\n <li><p style=\"padding:0px;\">内容管理(単ページの内容、文章の内容、製品の内容…ですカスタム・コンテンツ・モデルです)</p></li>\n <li><p style=\"padding:0px;\">サイト配置、会社情報です</p></li>\n <li><p style=\"padding:0px;\">カスタムラベル(カスタムフロントラベル)です。</p></li>\n <li><p style=\"padding:0px;\">フロントの模造ラベルです</p></li>\n <li><p style=\"padding:0px;\">ラウンドキャスト画像です</p></li>\n <li><p style=\"padding:0px;\">多条件スクリーニングです</p></li>\n <li><p style=\"padding:0px;\">サイトマップです</p></li>\n <li><p style=\"padding:0px;\">友情のリンクです</p></li>\n <li><p style=\"padding:0px;\">カスタムフォーム</p></li>\n <li><p style=\"padding:0px;\">メッセージを残します</p></li>\n <li><p style=\"padding:0px;\">記事のリンクです</p></li>\n <li><p style=\"padding:0px;\">多条件検索です</p></li>\n <li><p style=\"padding:0px;\">コンテンツ権限です</p></li>\n <li><p style=\"padding:0px;\">会員機能(ログイン、登録、パスワードの返却、パスワードの変更、残高、ポイント、脱退)です。</p></li>\n <li><p style=\"padding:0px;\">会員フィールドです</p></li>\n <li><p style=\"padding:0px;\">メンバーシップレベル(コラムやコンテンツの閲覧権限を設定します)</p></li>\n <li><p style=\"padding:0px;\">記事のレビュー(返信、レビュー)です。</p></li>\n <li><p style=\"padding:0px;\">私のコメントです</p></li>\n</ul>\n<p><br></p>', '', '', '', '紹介しますBadouCMSはThinkPHP8 + Layui + Jqueryなどの人気技術スタックをベースとしたオープンソースのwebサイト管理システムで、多言語、多モデル、多条件検索、コンテンツ権限、会員機能、記事レビュー、記事リンク、百度プッシュ、ローキャストマップ、多条件スクリーニング、webサイトマップなどをサポートしています...', 0, '1', '0', '0', '0', 2, 0, 0, 'admin', 'admin', '2025-10-26 22:57:54', '2025-11-04 09:17:12', '', '', '', '10', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (179, 'cn', '7', '', '瑜伽服运动韩版宽松百搭裤', '', '', '', '', '', '', '2025-10-26 23:06:22', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg,/uploads/20251026/d923c75065cc6ae0971b20bc8ce4cfb8.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><img src=\"/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg\" alt=\"82097961270ad5068adbb6b87f540031.jpg\" /></h3><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br /></h3><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br /></h3><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">介绍</h3><p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS 基于 ThinkPHP8 + Layui + Jquery 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">功能列表</h3><ul class=\"list-paddingleft-2\"><li><p style=\"padding:0px;\">区域管理（多语言）</p></li><li><p style=\"padding:0px;\">模型管理（自定义内容模型）</p></li><li><p style=\"padding:0px;\">模型字段管理（自定义模型字段）</p></li><li><p style=\"padding:0px;\">栏目管理</p></li><li><p style=\"padding:0px;\">内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p style=\"padding:0px;\">站点配置、公司信息</p></li><li><p style=\"padding:0px;\">定制标签（自定义前台标签）</p></li><li><p style=\"padding:0px;\">前台模版标签</p></li><li><p style=\"padding:0px;\">轮播图片</p></li><li><p style=\"padding:0px;\">多条件筛选</p></li><li><p style=\"padding:0px;\">网站地图（sitemap）</p></li><li><p style=\"padding:0px;\">友情链接</p></li><li><p style=\"padding:0px;\">自定义表单</p></li><li><p style=\"padding:0px;\">留言信息</p></li><li><p style=\"padding:0px;\">文章内链</p></li><li><p style=\"padding:0px;\">多条件搜索</p></li><li><p style=\"padding:0px;\">内容权限</p></li><li><p style=\"padding:0px;\">会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p style=\"padding:0px;\">会员字段</p></li><li><p style=\"padding:0px;\">会员等级(设置栏目与内容浏览权限)</p></li><li><p style=\"padding:0px;\">文章评论(回复、审核)</p></li><li><p style=\"padding:0px;\">我的评论</p></li></ul><p><br /></p>', '', '', '', '介绍BadouCMS 基于 ThinkPHP8 + Layui + Jquery 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模型字段）栏目管理内容管理（单页内容、...', 0, '1', '0', '0', '0', 5, 0, 0, 'admin', 'admin', '2025-10-26 23:08:55', '2025-11-04 09:15:26', '', '', '', '11', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (180, 'en', '94', '', 'Yoga wear, loose and versatile Korean-style sports pants', '', '', '', '', '', '', '2025-10-26 23:06:22', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg,/uploads/20251026/d923c75065cc6ae0971b20bc8ce4cfb8.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><img src=\"/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg\" alt=\"82097961270ad5068adbb6b87f540031.jpg\"></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Introduction</h3>\n<p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS is an open-source website management system based on popular technology stacks such as ThinkPHP8 + Layui + Jquery. It supports multi-language, multi-model, multi-condition search, content permissions, member functions, article comments, article internal links, Baidu push, carousel images, multi-condition filtering, site maps, etc.</p>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Function list</h3>\n<ul class=\"list-paddingleft-2\">\n <li><p style=\"padding:0px;\">Regional Management (Multilingual</p></li>\n <li><p style=\"padding:0px;\">Model Management (Custom Content Model)</p></li>\n <li><p style=\"padding:0px;\">Model Field Management (Custom Model Fields)</p></li>\n <li><p style=\"padding:0px;\">Column management</p></li>\n <li><p style=\"padding:0px;\">Content management (single-page content, article content, product content...) \"Custom Content Model</p></li>\n <li><p style=\"padding:0px;\">Site configuration, company information</p></li>\n <li><p style=\"padding:0px;\">Customized tags (Custom front desk tags)</p></li>\n <li><p style=\"padding:0px;\">Front desk template tag</p></li>\n <li><p style=\"padding:0px;\">Carousel image</p></li>\n <li><p style=\"padding:0px;\">Multi-condition screening</p></li>\n <li><p style=\"padding:0px;\">sitemap</p></li>\n <li><p style=\"padding:0px;\">Friendship link</p></li>\n <li><p style=\"padding:0px;\">Custom form</p></li>\n <li><p style=\"padding:0px;\">Message information</p></li>\n <li><p style=\"padding:0px;\">Internal links within the article</p></li>\n <li><p style=\"padding:0px;\">Multi-condition search</p></li>\n <li><p style=\"padding:0px;\">Content permission</p></li>\n <li><p style=\"padding:0px;\">Member functions (login, registration, password retrieval, password modification, balance, points, logout)</p></li>\n <li><p style=\"padding:0px;\">Member field</p></li>\n <li><p style=\"padding:0px;\">Membership level (Setting column and content browsing permissions)</p></li>\n <li><p style=\"padding:0px;\">Article Comments (Replies, Reviews)</p></li>\n <li><p style=\"padding:0px;\">My comment</p></li>\n</ul>\n<p><br></p>', '', '', '', 'This article introduces BadouCMS, an open-source website management system based on popular technology stacks such as ThinkPHP8 + Layui + Jquery. It supports multi-language, multi-model, multi-condition search, content permissions, member functions, article comments, internal links within articles, ...', 0, '1', '0', '0', '0', 1, 0, 0, 'admin', 'admin', '2025-10-26 23:08:55', '2025-11-04 09:15:29', '', '', '', '11', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (181, 'oe', '95', '', 'Eine yoga-robe mit lockeren und lockeren hosen in südkorea', '', '', '', '', '', '', '2025-10-26 23:06:22', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg', '/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg,/uploads/20251026/d923c75065cc6ae0971b20bc8ce4cfb8.jpg', '', '<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><img src=\"/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg\" alt=\"82097961270ad5068adbb6b87f540031.jpg\"></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\"><br></h3>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Vorstellung.</h3>\n<p style=\"padding:0px;font-size:16px;color:rgb(33,37,41);\">BadouCMS basiert auf einem system zur online-verwaltung Von thinkphp-8 + Layui + Jquery, das mehrsprachigkeit, vielseitige modelle, die vielseitige suche, die zugriffsfunktionen, die zugriffsfunktionen, die wortkommentare, die kette des profs, die promethie-kette, das kreuzungsdiagramm, die feldkarte der website und so weiter unterstützt.</p>\n<h3 style=\"margin:0px;line-height:1.2;color:rgb(33,37,41);font-size:16px;padding:0px;\">Liste der funktionen</h3>\n<ul class=\"list-paddingleft-2\">\n <li><p style=\"padding:0px;\">Regional management (mehrsprachig)</p></li>\n <li><p style=\"padding:0px;\">Klosterverwaltung (ein selbstdefiniertes inhaltsmodell)</p></li>\n <li><p style=\"padding:0px;\">Verwaltung des modellfeldes (benutzerdefiniert für modellfeld)</p></li>\n <li><p style=\"padding:0px;\">Er hält nach zielerfassung ausschau.</p></li>\n <li><p style=\"padding:0px;\">Regulierung der inhalte (seite 1, seite, text, text) Ein benutzerdefiniertes inhaltsmodell</p></li>\n <li><p style=\"padding:0px;\">Seiten einrichten, informationen zur firma</p></li>\n <li><p style=\"padding:0px;\">Standard-reiter (benutzerdefiniert als vorlage)</p></li>\n <li><p style=\"padding:0px;\">Rezeptmodell modell sind</p></li>\n <li><p style=\"padding:0px;\">Ja, das ist eine welpe.</p></li>\n <li><p style=\"padding:0px;\">Eine überprüfung vieler bedingungen</p></li>\n <li><p style=\"padding:0px;\">Eine webmap (sitemap)</p></li>\n <li><p style=\"padding:0px;\">Durch freundschaft.</p></li>\n <li><p style=\"padding:0px;\">Formulare auswerten.</p></li>\n <li><p style=\"padding:0px;\">Eine nachricht.</p></li>\n <li><p style=\"padding:0px;\">Die kette des artikels</p></li>\n <li><p style=\"padding:0px;\">Suche unter mehreren bedingungen.</p></li>\n <li><p style=\"padding:0px;\">Inhaltszugriff gewährt</p></li>\n <li><p style=\"padding:0px;\">Mitgliederfunktionen (loggen, anmelden, passwort erhalten, passwort ändern, kontostand, verdienste, ausstieg)</p></li>\n <li><p style=\"padding:0px;\">wärter</p></li>\n <li><p style=\"padding:0px;\">Stufen der mitglieder (festlegung der leiste und zugriffsrechte auf inhalt)</p></li>\n <li><p style=\"padding:0px;\">Kommentare [kommentare, überprüfung]</p></li>\n <li><p style=\"padding:0px;\">Mein urteil.</p></li>\n</ul>\n<p><br></p>', '', '', '', 'Einführung des world wide web management-systems, das auf dem modul thinkraph + 8 + Layui + Jquery und dem temporären webdienst der modestube beruht und daher mehrsprachigkeit, vielseitige modelle, vielseitige zugriffsmöglichkeiten, die zugriffsfunktion, die zugriffsfunktion, die wortkonsole, die...', 0, '1', '0', '0', '0', 1, 0, 0, 'admin', 'admin', '2025-10-26 23:08:56', '2025-11-04 09:15:32', '', '', '', '11', '');
