INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (165, 'oe', '98', '', 'Schnecken cken falsche spule, schultergriff und ein schmaler rock', '', '', '', '', '', '', '2025-10-26 17:43:43', '/uploads/20251026/19a3033d4ccac8dfa8805bf577659ebe.jpg', '/uploads/20251026/19a3033d4ccac8dfa8805bf577659ebe.jpg,/uploads/20251029/60af7ee88d87f8084193e01260d05a56.jpeg,/uploads/20251026/82097961270ad5068adbb6b87f540031.jpg', '', '<p>Schnecken zwei perverse spinnenklammern bilden eine porno-falte, seitlich eine dünne gürtelröte und eine perlschattenfalte eine porno-falte</p>\n<p>Schnecken cken falsche spule, schultergriff und ein schmaler rock</p>\n<p>Schnecken cken falsche spule, schultergriff und ein schmaler rock</p>\n<p>Schnecken cken falsche spule, schultergriff und ein schmaler rock</p>\n<p>Schnecken cken falsche spule, schultergriff und ein schmaler rock</p>\n<p><img src=\"/uploads/20251026/19a3033d4ccac8dfa8805bf577659ebe.jpg\" alt=\"19a3033d4ccac8dfa8805bf577659ebe.jpg\"></p>', '', '', '', 'Schnecken cken falsche spule, schultergriff und ein schmaler rock', 0, '1', '0', '0', '0', 2, 0, 0, 'admin', 'admin', '2025-10-26 17:44:25', '2025-11-04 09:24:05', '', '', '', '7', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (110, 'cn', '34', '', 'badoucms功能列表', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '', '', '<p><br /></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><h3>功能列表</h3><ul class=\"list-paddingleft-2\"><li><p>区域管理（多语言）</p></li><li><p>模型管理（自定义内容模型）</p></li><li><p>模型字段管理（自定义模型字段）</p></li><li><p>栏目管理</p></li><li><p>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p>站点配置、公司信息</p></li><li><p>定制标签（自定义前台标签）</p></li><li><p>前台模版标签</p></li><li><p>轮播图片</p></li><li><p>多条件筛选</p></li><li><p>网站地图（sitemap）</p></li><li><p>友情链接</p></li><li><p>自定义表单</p></li><li><p>留言信息</p></li><li><p>文章内链</p></li><li><p>多条件搜索</p></li><li><p>百度推送</p></li><li><p>内容权限</p></li><li><p>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p>会员字段</p></li><li><p>会员等级(设置栏目与内容浏览权限)</p></li><li><p>文章评论(回复、审核)</p></li><li><p>我的评论</p></li></ul>', 'bc', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模...', 3, '1', '0', '0', '0', 30, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:23:11', '4', '', '', '18', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (215, 'en', '110', '', 'badoucms feature list', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '', '', '<p><br /></p><h3>Introduction</h3><p>BadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel, multi-condition filtering, site map, etc. </p><h3>Feature List</h3><ul class=\"list-paddingleft-2\"><li><p>Region management (multi-language)</p></li><li><p>Model management (custom content model)</p></li><li><p>Model field management (custom model field)</p></li><li><p>Column management</p></li><li><p>Content management (single page content, article content, product content...custom content model)</p></li><li><p>Site configuration, company information</p></li><li><p>Custom tags (custom front-end tags)</p></li><li><p>Front-end template tags</p></li><li><p>Carousel images</p></li><li><p>Multi-condition filtering</p></li><li><p>Site map (s </p></li><li><p>Friendly links</p></li><li><p>Custom forms</p></li><li><p>Message information</p></li><li><p>Article internal links</p></li><li><p>Multi-condition search</p></li><li><p>Baidu push</p></li><li><p>Content permissions</p></li><li><p>Member functions (login, register, retrieve password, change password, balance, points, log out)</p></li><li><p>Member fields</p></li><li><p>Member level (set column and content browsing permissions)</p></li><li><p>Article comments (reply, review)</p></li><li><p>My comments</p></li></ul>', 'bc', '', '', 'IntroductionBadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comme...', 3, '1', '0', '0', '0', 30, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:23:11', '4', '', '', '18', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (157, 'jp', '127', '', 'お問い合わせ', '#333333', '', '', 'Admin', '本站', '', '2025-10-26 09:50:06', '', '', '', '', '', '', '', '', 255, '1', '0', '0', '0', 0, 0, 0, 'Admin', 'Admin', '2025-10-26 09:50:06', '2025-10-26 09:50:06', '4', '0', '', '', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (237, 'oe', '117', '', 'Plattformbetrieb', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/6941ed287ece8bba00ad53273beadf45.jpeg', '', '', '<p><strong>Aufgaben:</strong></p><p>1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;</p><p>2. Teilnahme an und Optimierung des Geschäftsbetriebsprozesses der Abteilung, um die Zusammenarbeit im Team sicherzustellen;</p><p>3. Bereitstellung von Plattform-Geschäftsberatungsdiensten für Benutzer;</p><p>4. Entgegennahme und Lösung von Kundenbeschwerden im Rahmen der Genehmigung;</p><p>5. Aufzeichnen und Bearbeiten von Videos von Online-Aktivitäten, Entdecken hervorragender Arbeiten und einfaches Bearbeiten und Verarbeiten von Hintergrundinformationen;</p><p>6. Zusammenarbeit mit anderen Abteilungen des Unternehmens. </p><p><br /></p><p><strong>Anforderungen:</strong></p><p>1. Hochschulabschluss oder höher, Liebe zur Internetbranche;</p><p>2. Starkes Verantwortungsbewusstsein, fleißig, positiv und fröhlich;</p><p>3. Gutes Image, eloquent, Standard-Mandarin;</p><p>4. Computerkenntnisse, regelmäßiger Internetzugang und Fähigkeit, Office und andere zugehörige Bürosoftware zu verwenden;</p><p>5. Fähigkeit, sich an Tag- und Nachtschichtarbeit anzupassen;</p><p>Hinweis: Je nach persönlichen Fähigkeiten und Fachkenntnissen bietet das Unternehmen mehr Raum für Entwicklung und Aufstieg.</p><p><br /></p><p><strong>Arbeitsadresse:</strong>                        </p><h2>Beiyuan Road, Chaoyang District, Peking</h2>', '', '', '', 'Aufgaben:1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;2. Teilnahme an und Optimierung des Geschäftsbetriebsprozesses der Abteilung, um die Zusammenarbeit im Team sicherzustellen;3. Bereitstellun...', 255, '1', '0', '0', '0', 5, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:25:25', '4', '', '', '24', '');
