INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (111, 'cn', '34', '33,34', 'badoucms 正式上线1.0.0 版本', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p>\n	<img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" />\n</p>\n<h3>\n	介绍\n</h3>\n<p>\n	BadouCMS 基于 Layui + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。\n</p>\n<h3>\n	功能列表\n</h3>\n<ul class=\"list-paddingleft-2\">\n	<li>\n		<p>\n			区域管理（多语言）\n		</p>\n	</li>\n	<li>\n		<p>\n			模型管理（自定义内容模型）\n		</p>\n	</li>\n	<li>\n		<p>\n			模型字段管理（自定义模型字段）\n		</p>\n	</li>\n	<li>\n		<p>\n			栏目管理\n		</p>\n	</li>\n	<li>\n		<p>\n			内容管理（单页内容、文章内容、产品内容...自定义内容模型）\n		</p>\n	</li>\n	<li>\n		<p>\n			站点配置、公司信息\n		</p>\n	</li>\n	<li>\n		<p>\n			定制标签（自定义前台标签）\n		</p>\n	</li>\n	<li>\n		<p>\n			前台模版标签\n		</p>\n	</li>\n	<li>\n		<p>\n			轮播图片\n		</p>\n	</li>\n	<li>\n		<p>\n			多条件筛选\n		</p>\n	</li>\n	<li>\n		<p>\n			网站地图（sitemap）\n		</p>\n	</li>\n	<li>\n		<p>\n			友情链接\n		</p>\n	</li>\n	<li>\n		<p>\n			自定义表单\n		</p>\n	</li>\n	<li>\n		<p>\n			留言信息\n		</p>\n	</li>\n	<li>\n		<p>\n			文章内链\n		</p>\n	</li>\n	<li>\n		<p>\n			多条件搜索\n		</p>\n	</li>\n	<li>\n		<p>\n			百度推送\n		</p>\n	</li>\n	<li>\n		<p>\n			内容权限\n		</p>\n	</li>\n	<li>\n		<p>\n			会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)\n		</p>\n	</li>\n	<li>\n		<p>\n			会员字段\n		</p>\n	</li>\n	<li>\n		<p>\n			会员等级(设置栏目与内容浏览权限)\n		</p>\n	</li>\n	<li>\n		<p>\n			文章评论(回复、审核)\n		</p>\n	</li>\n	<li>\n		<p>\n			我的评论\n		</p>\n	</li>\n</ul>', 'badoucms,a,b', '', '', '介绍BadouCMS 基于 Layui + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（...', 1, '1', '1', '1', '1', 103, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-11-03 15:37:48', '4', '', '请先充值', '1', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (112, 'cn', '34', '33,34', 'badoucms基于thinkphp8+vue3的网站管理系统', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/d5b47d3f753508adbb095aa1883b44b6.jpg', '', '', '<p><br /></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><p><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><h3>功能列表</h3><ul class=\"list-paddingleft-2\"><li><p>区域管理（多语言）</p></li><li><p>模型管理（自定义内容模型）</p></li><li><p>模型字段管理（自定义模型字段）</p></li><li><p>栏目管理</p></li><li><p>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p>站点配置、公司信息</p></li><li><p>定制标签（自定义前台标签）</p></li><li><p>前台模版标签</p></li><li><p>轮播图片</p></li><li><p>多条件筛选</p></li><li><p>网站地图（sitemap）</p></li><li><p>友情链接</p></li><li><p>自定义表单</p></li><li><p>留言信息</p></li><li><p>文章内链</p></li><li><p>多条件搜索</p></li><li><p>百度推送</p></li><li><p>内容权限</p></li><li><p>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p>会员字段</p></li><li><p>会员等级(设置栏目与内容浏览权限)</p></li><li><p>文章评论(回复、审核)</p></li><li><p>我的评论</p></li></ul>', 'cms', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模...', 2, '1', '0', '0', '0', 16, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:22:36', '4', '', '', '17', '');
