INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (114, 'cn', '34', '', 'BadouCMS快速入门', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>图片缩放函数：resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>参数：$src_image=源图片路径 （必填）</p><p>$max_width=缩放后的宽度</p><p>$max_height=缩放后的高度</p><p>$img_quality=图片质量</p><p>在标签中使用：<code>{$item.ico|resize_img=\'10\',\'10\'}</code></p>', 'wy', '', '', '测试新闻1', 255, '1', '0', '0', '0', 62, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:21:45', '4', '', '', '15', '');
