INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (242, 'en', '116', '', 'Tmall Operations', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/f5714df3144c33c96ef0fa0f53965a5f.jpeg', '', '', '<p><strong>Job Responsibilities:</strong></p><p>1. Responsible for the business support work of platform operations and ensure the stable development of platform business;</p><p>2. Participate in and optimize the department\'s business operation process to ensure team collaboration;</p><p>3. Provide platform business consulting services to users;</p><p>4. Accept customer complaints and resolve them within the scope of authorization;</p><p>5. Record and edit videos of online activities, discover excellent works, and simply edit and process background information;</p><p>6. Cooperate with other departments of the company. </p><p><br /></p><p><strong>Job Requirements:</strong></p><p>1. College degree or above, love the Internet industry;</p><p>2. Strong sense of responsibility, hardworking, positive and cheerful;</p><p>3. Good image, eloquent, standard Mandarin;</p><p>4. Proficient in computer, frequent Internet access, and able to use office and other related office software;</p><p>5. Able to adapt to day and night shift work;</p><p>Note: Based on personal ability and expertise, the company will provide more development and promotion space.</p><p><br /></p><p><strong>Work Address:</strong>                        </p><h2>Beiyuan Road, Chaoyang District, Beijing</h2>', '', '', '', 'Job Responsibilities:1. Responsible for the business support work of platform operations and ensure the stable development of platform business;2. Participate in and optimize the department&#039;s business operation process to ensure team collaboration;3. Provide platform business consulting services to ...', 255, '1', '0', '0', '0', 6, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:29:34', '4', '', '', '26', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (241, 'jp', '118', '', 'タオバオ運営', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/bce882d6ddebc9f7e91248392e891fe0.jpeg', '/storage/default/20241126/teams4f3c94f4696e55452f157173f340e2d321252398a.jpeg,/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg', '', '<p><strong>職務内容:</strong></p><p style=\"text-align:center;\"><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><p><br /></p><p>1. プラットフォーム運用の業務サポート業務を担当し、プラットフォーム事業の安定した発展を確保する。</p><p>2. 部門の業務運用プロセスに参加し、最適化してチームのコラボレーションを確保する。</p><p>3. ユーザーにプラットフォーム事業に関するコンサルティング サービスを提供する。</p><p>4. 顧客からの苦情を受け付け、権限の範囲内で解決する。</p><p>5.オンライン活動ビデオを録画および編集し、優れた作品を発掘し、背景情報を簡単に編集および処理します。</p><p>6. 会社の他の部門と協力します。</p><p style=\"text-align:center;\"><img src=\"/storage/default/20241130/logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" alt=\"logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" /></p><p><strong>仕事の要件:</strong></p><p>1. 大学卒業以上、インターネット業界が好き。</p><p>2. 責任感が強く、現実的で勤勉、前向きで明るい性格。</p><p>3.良いイメージ、雄弁、標準的な中国語。</p><p>4. コンピュータの使用に習熟し、頻繁にインターネットにアクセスでき、Officeおよびその他の関連Officeソフトウェアを使用できる。</p><p>5. 昼夜シフト勤務システムに適応できる。</p><p>注：個人の能力と専門知識に基づいて、会社はより多くの開発および昇進の余地を提供します。</p><p><br /></p><p><strong>勤務先住所：</strong>                              </p><h2>北京市朝陽区北園路</h2>', '', '', '', '職務内容:1. プラットフォーム運用の業務サポート業務を担当し、プラットフォーム事業の安定した発展を確保する。2. 部門の業務運用プロセスに参加し、最適化してチームのコラボレーションを確保する。3. ユーザーにプラットフォーム事業に関するコンサルティング サービスを提供する。4. 顧客からの苦情を受け付け、権限の...', 255, '1', '0', '0', '0', 10, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:25:34', '4', '', '', '25', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (240, 'oe', '117', '', 'Taobao-Operationen', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/bce882d6ddebc9f7e91248392e891fe0.jpeg', '/storage/default/20241126/teams4f3c94f4696e55452f157173f340e2d321252398a.jpeg,/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg', '', '<p><strong>Aufgaben:</strong></p><p style=\"text-align:center;\"><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><p><br /></p><p>1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;</p><p>2. Teilnahme an abteilungsbezogenen Geschäftsbetriebsprozessen und deren Optimierung, um die Zusammenarbeit im Team sicherzustellen;</p><p>3. Bereitstellung von Plattform-Geschäftsberatungsdiensten für Benutzer;</p><p>4. Annahme von Kundenbeschwerden und deren Lösung im Rahmen der Genehmigung;</p><p>5. Online-Aktivitätsvideos aufnehmen und bearbeiten, hervorragende Arbeiten entdecken und einfach Hintergrundinformationen bearbeiten und verarbeiten;</p><p>6. Mit anderen Abteilungen des Unternehmens zusammenarbeiten. </p><p style=\"text-align:center;\"><img src=\"/storage/default/20241130/logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" alt=\"logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" /></p><p><strong>Stellenanforderungen:</strong></p><p>1. Hochschulabschluss oder höher, Liebe zur Internetbranche;</p><p>2. Starkes Verantwortungsbewusstsein, bodenständig und fleißig, positive und fröhliche Persönlichkeit;</p><p>3. Gutes Image, eloquent, Standard-Mandarin;</p><p>4. Kompetenter Computergebrauch, häufiger Internetzugang und Fähigkeit, Office und andere zugehörige Bürosoftware zu verwenden;</p><p>5. Fähigkeit, sich an Tag- und Nachtschichtarbeitssysteme anzupassen;</p><p>Hinweis: Je nach persönlichen Fähigkeiten und Fachkenntnissen bietet das Unternehmen mehr Raum für Entwicklung und Aufstieg.</p><p><br /></p><p><strong>Arbeitsadresse:</strong>                          </p><h2>Beiyuan Road, Chaoyang District, Beijing</h2>', '', '', '', 'Aufgaben:1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;2. Teilnahme an abteilungsbezogenen Geschäftsbetriebsprozessen und deren Optimierung, um die Zusammenarbeit im Team sicherzustellen;3. Berei...', 255, '1', '0', '0', '0', 10, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:25:34', '4', '', '', '25', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (239, 'en', '116', '', 'Taobao Operations', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/bce882d6ddebc9f7e91248392e891fe0.jpeg', '/storage/default/20241126/teams4f3c94f4696e55452f157173f340e2d321252398a.jpeg,/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg', '', '<p><strong>Job Responsibilities:</strong></p><p style=\"text-align:center;\"><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><p><br /></p><p>1. Responsible for the business support work of platform operations and ensure the stable development of platform business;</p><p>2. Participate in and optimize departmental business operation processes to ensure team collaboration;</p><p>3. Provide platform business consulting services to users;</p><p>4. Accept customer complaints and resolve them within the scope of authorization;</p><p>5. Record and edit online activity videos, discover excellent works, and simply edit and process background information;</p><p>6. Cooperate with other departments of the company. </p><p style=\"text-align:center;\"><img src=\"/storage/default/20241130/logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" alt=\"logo-b834a5b93f4d5ee35f256198252216570f75fc9a0.png\" /></p><p><strong>Job requirements:</strong></p><p>1. College degree or above, love the Internet industry;</p><p>2. Strong sense of responsibility, down-to-earth and diligent, positive and cheerful personality;</p><p>3. Good image, eloquent, standard Mandarin;</p><p>4. Proficient in computer use, frequent Internet access, and able to use office and other related office software;</p><p>5. Able to adapt to day and night shift work system;</p><p>Note: Based on personal ability and expertise, the company will provide more development and promotion space.</p><p><br /></p><p><strong>Work address:</strong>                          </p><h2>Beiyuan Road, Chaoyang District, Beijing</h2>', '', '', '', 'Job Responsibilities:1. Responsible for the business support work of platform operations and ensure the stable development of platform business;2. Participate in and optimize departmental business operation processes to ensure team collaboration;3. Provide platform business consulting services to us...', 255, '1', '0', '0', '0', 10, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:25:34', '4', '', '', '25', '');
