INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (148, 'cn', '34', '', '建筑行业网站模板', '', '', '', 'Admin', '', '', '2025-10-24 15:17:20', '/uploads/20250622/83f70d6c57f86c51e8666b16afcb4830.jpeg', '', '', '', '', '', '', '', 252, '1', '0', '0', '0', 41, 0, 0, 'Admin', 'admin', '2025-10-24 15:17:20', '2025-10-27 17:21:34', '4', '', '', '13', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (208, 'jp', '112', '', 'BadouCMSを使い始める', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/4772e65f8810a17712b564b838be7f18.jpeg', '', '', '<p><br /></p><p><br /></p><h2>画像拡大縮小関数: resize_img</h2><p><code>resize_img(string $src_image, int $max_width = 0, int $max_height = 0, int $img_quality = 90): string</code></p><p>パラメータ: $src_image = ソース画像のパス（必須）</p><p>$max_width = 拡大縮小後の幅</p><p>$max_height = 拡大縮小後の高さ</p><p>$img_quality = 画像の品質</p><p>タグで使用: <code>{$item.ico|resize_img=\'10\',\'10\'></code></p>', 'wy', '', '', 'テストニュース1', 255, '1', '0', '0', '0', 62, 0, 0, 'Admin', 'admin', '2025-06-22 19:35:41', '2025-10-27 17:21:44', '4', '', '', '15', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (149, 'cn', '34', '33,34', 'badoucms 正式上线1.0.0 版本', '', '', '', '', '', '', '2025-10-24 15:52:08', '/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p>\n	<img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" />\n</p>\n<h3>\n	介绍\n</h3>\n<p>\n	BadouCMS 基于 Layui + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。\n</p>\n<h3>\n	功能列表\n</h3>\n<ul class=\"list-paddingleft-2\">\n	<li>\n		<p>\n			区域管理（多语言）\n		</p>\n	</li>\n	<li>\n		<p>\n			模型管理（自定义内容模型）\n		</p>\n	</li>\n	<li>\n		<p>\n			模型字段管理（自定义模型字段）\n		</p>\n	</li>\n	<li>\n		<p>\n			栏目管理\n		</p>\n	</li>\n	<li>\n		<p>\n			内容管理（单页内容、文章内容、产品内容...自定义内容模型）\n		</p>\n	</li>\n	<li>\n		<p>\n			站点配置、公司信息\n		</p>\n	</li>\n	<li>\n		<p>\n			定制标签（自定义前台标签）\n		</p>\n	</li>\n	<li>\n		<p>\n			前台模版标签\n		</p>\n	</li>\n	<li>\n		<p>\n			轮播图片\n		</p>\n	</li>\n	<li>\n		<p>\n			多条件筛选\n		</p>\n	</li>\n	<li>\n		<p>\n			网站地图（sitemap）\n		</p>\n	</li>\n	<li>\n		<p>\n			友情链接\n		</p>\n	</li>\n	<li>\n		<p>\n			自定义表单\n		</p>\n	</li>\n	<li>\n		<p>\n			留言信息\n		</p>\n	</li>\n	<li>\n		<p>\n			文章内链\n		</p>\n	</li>\n	<li>\n		<p>\n			多条件搜索\n		</p>\n	</li>\n	<li>\n		<p>\n			百度推送\n		</p>\n	</li>\n	<li>\n		<p>\n			内容权限\n		</p>\n	</li>\n	<li>\n		<p>\n			会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)\n		</p>\n	</li>\n	<li>\n		<p>\n			会员字段\n		</p>\n	</li>\n	<li>\n		<p>\n			会员等级(设置栏目与内容浏览权限)\n		</p>\n	</li>\n	<li>\n		<p>\n			文章评论(回复、审核)\n		</p>\n	</li>\n	<li>\n		<p>\n			我的评论\n		</p>\n	</li>\n</ul>', 'badoucms,a,b', '', '', '介绍BadouCMS 基于 Layui + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（...', 1, '1', '1', '1', '1', 107, 0, 0, 'Admin', 'admin', '2025-10-24 15:52:08', '2025-11-03 21:35:47', '4', '', '请先充值', '1', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (150, 'cn', '33', '33,34', 'badoucms基于thinkphp8+vue3的网站管理系统', '', '', '', '', '', '', '2025-10-24 15:52:08', '/uploads/20250622/dfd0c39345168c3bc085239ec741796b.jpg', '', '', '<p><br /></p><h3>介绍</h3><p>BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。</p><p><img src=\"/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" alt=\"teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg\" /></p><h3>功能列表</h3><ul class=\"list-paddingleft-2\"><li><p>区域管理（多语言）</p></li><li><p>模型管理（自定义内容模型）</p></li><li><p>模型字段管理（自定义模型字段）</p></li><li><p>栏目管理</p></li><li><p>内容管理（单页内容、文章内容、产品内容...自定义内容模型）</p></li><li><p>站点配置、公司信息</p></li><li><p>定制标签（自定义前台标签）</p></li><li><p>前台模版标签</p></li><li><p>轮播图片</p></li><li><p>多条件筛选</p></li><li><p>网站地图（sitemap）</p></li><li><p>友情链接</p></li><li><p>自定义表单</p></li><li><p>留言信息</p></li><li><p>文章内链</p></li><li><p>多条件搜索</p></li><li><p>百度推送</p></li><li><p>内容权限</p></li><li><p>会员功能(登录、注册、找回密码、修改密码、余额、积分、退出)</p></li><li><p>会员字段</p></li><li><p>会员等级(设置栏目与内容浏览权限)</p></li><li><p>文章评论(回复、审核)</p></li><li><p>我的评论</p></li></ul>', 'cms', '', '', '介绍BadouCMS 基于 Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus 等流行技术栈的开源网站管理系统，支持多语言、多模型、多条件搜索、内容权限、会员功能、文章评论、文章内链、百度推送、轮播图、多条件筛选、网站地图等。功能列表区域管理（多语言）模型管理（自定义内容模型）模型字段管理（自定义模...', 2, '1', '0', '0', '0', 23, 0, 0, 'Admin', 'admin', '2025-10-24 15:52:08', '2025-11-03 18:03:33', '4', '', '', '4', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (200, 'en', '110', '110,113', 'badoucms officially launched version 1.0.0', '', '', '', '', '', '', '2025-06-22 19:35:41', '/uploads/20250622/7012b6e8afbaaec9eea58e161306e4fe.jpg', '/storage/default/20241126/teams23ad8d1e14db9eb4ee9374c9a793c78e593829078.jpeg,/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg', '', '<p>\n<img src=\"/storage/default/20241126/teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" alt=\"teams39754bbeea387dc5326bde7c03b201b34036fac70.jpeg\" />\n</p>\n<h3>\nIntroduction\n</h3>\n<p>\nBadouCMS is an open-source website management system based on a popular technology stack including Layui, ThinkPHP8, TypeScript, Vite, Pinia, and Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership features, article comments, internal links, Baidu push notifications, carousels, multi-condition filtering, sitemaps, and more.\n</p>\n<h3>\nFeature List\n</h3>\n<ul class=\"list-paddingleft-2\">\n<li>\n<p>\nRegion Management (Multilingual)\n</p>\n</li>\n<li>\n<p>\nModel Management (Custom Content Model)\n</p>\n</li>\n<li>\n<p>\nModel Field Management (Custom Model Fields)\n</p>\n</li>\n<li>\n<p>\nColumn Management\n</p>\n</li>\n<li>\n<p>\nContent Management (Custom Content Models for Single Page Content, Article Content, Product Content...)\n</p>\n</li>\n<li>\n<p>\nSite Configuration, Company Information\n</p>\n</li>\n<li>\n<p>\nCustom Tags (Custom Front-End Tags)\n</p>\n</li>\n<li>\n<p>\nFront-End Template Tags\n</p>\n</li>\n<li>\n<p>\nCarousel Images\n</p>\n</li>\n<li>\n<p>\nMulti-Criteria Filtering\n</p>\n</li>\n<li>\n<p>\nSitemap\n</p>\n</li>\n<li>\n<p>\nFriendly Links\n</p>\n</li>\n<li>\n<p>\nCustom Forms\n</p>\n</li>\n<li>\n<p>\nMessages\n</p>\n</li>\n<li>\n<p>\nArticle Links\n</p>\n</li>\n<li>\n<p>\nMulti-Criteria Search\n</p>\n</li>\n<li>\n<p>\nBaidu Push\n</p>\n</li>\n<li>\n<p>\nContent Permissions\n</p>\n</li>\n<li>\n<p>\nMember functions (login, registration, password retrieval, password change, balance, points, logout)\n</p>\n</li>\n<li>\n<p>\nMember fields\n</p>\n</li>\n<li>\n<p>\nMember level (setting column and content browsing permissions)\n</p>\n</li>\n<li>\n<p>\nArticle comments (reply, review)\n</p>\n</li>\n<li>\n<p>\nMy comments\n</p>\n</li>\n</ul>', 'badoucms,a,b', '', '', 'IntroductionBadouCMS is an open-source website management system based on a popular technology stack including Layui, ThinkPHP8, TypeScript, Vite, Pinia, and Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership features, articl...', 1, '1', '1', '1', '1', 116, 0, 0, 'Admin', 'admin', '2025-10-24 15:52:08', '2025-11-03 15:37:51', '4', '', '请先充值', '1', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (243, 'oe', '117', '', 'Tmall-Operationen', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/f5714df3144c33c96ef0fa0f53965a5f.jpeg', '', '', '<p><strong>Aufgaben:</strong></p><p>1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;</p><p>2. Teilnahme an und Optimierung des Geschäftsbetriebsprozesses der Abteilung, um die Zusammenarbeit im Team sicherzustellen;</p><p>3. Bereitstellung von Plattform-Geschäftsberatungsdiensten für Benutzer;</p><p>4. Entgegennahme und Lösung von Kundenbeschwerden im Rahmen der Genehmigung;</p><p>5. Aufzeichnen und Bearbeiten von Videos von Online-Aktivitäten, Entdecken hervorragender Arbeiten und einfaches Bearbeiten und Verarbeiten von Hintergrundinformationen;</p><p>6. Zusammenarbeit mit anderen Abteilungen des Unternehmens. </p><p><br /></p><p><strong>Anforderungen:</strong></p><p>1. Hochschulabschluss oder höher, Liebe zur Internetbranche;</p><p>2. Starkes Verantwortungsbewusstsein, fleißig, positiv und fröhlich;</p><p>3. Gutes Image, eloquent, Standard-Mandarin;</p><p>4. Computerkenntnisse, regelmäßiger Internetzugang und Fähigkeit, Office und andere zugehörige Bürosoftware zu verwenden;</p><p>5. Fähigkeit, sich an Tag- und Nachtschichtarbeit anzupassen;</p><p>Hinweis: Je nach persönlichen Fähigkeiten und Fachkenntnissen bietet das Unternehmen mehr Raum für Entwicklung und Aufstieg.</p><p><br /></p><p><strong>Arbeitsadresse:</strong>                        </p><h2>Beiyuan Road, Chaoyang District, Peking</h2>', '', '', '', 'Aufgaben:1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;2. Teilnahme an und Optimierung des Geschäftsbetriebsprozesses der Abteilung, um die Zusammenarbeit im Team sicherzustellen;3. Bereitstellun...', 255, '1', '0', '0', '0', 6, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:29:34', '4', '', '', '26', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (244, 'jp', '118', '', 'Tmallオペレーション', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/f5714df3144c33c96ef0fa0f53965a5f.jpeg', '', '', '<p><strong>職務内容:</strong></p><p>1. プラットフォーム運営の業務サポート業務を担当し、プラットフォーム事業の安定的な発展を確保する。</p><p>2. 部門の業務運営プロセスに参加し、最適化してチームのコラボレーションを確保する。</p><p>3. ユーザーにプラットフォーム事業に関するコンサルティングサービスを提供する。</p><p>4. 顧客からの苦情を受け付け、権限の範囲内で解決する。</p><p>5. オンライン活動のビデオを録画および編集し、優れた作品を発掘し、背景情報を簡単に編集および処理する。</p><p>6. 社内の他部門と協力する。</p><p><br /></p><p><strong>職務要件:</strong></p><p>1. 大学卒業以上、インターネット業界が好き。</p><p>2. 責任感が強く、勤勉、前向きで明るい。</p><p>3. イメージが良く、雄弁、標準的な中国語を話せる。</p><p>4.コンピューターに精通し、インターネットに頻繁にアクセスでき、Office およびその他の関連 Office ソフトウェアを使用できる。</p><p>5. 昼夜を問わず勤務に適応できる。</p><p>注: 個人の能力と専門知識に基づいて、会社はより多くの開発および昇進の機会を提供します。</p><p><br /></p><p><strong>勤務地住所:</strong>                            </p><h2>北京市朝陽区北園路</h2>', '', '', '', '職務内容:1. プラットフォーム運営の業務サポート業務を担当し、プラットフォーム事業の安定的な発展を確保する。2. 部門の業務運営プロセスに参加し、最適化してチームのコラボレーションを確保する。3. ユーザーにプラットフォーム事業に関するコンサルティングサービスを提供する。4. 顧客からの苦情を受け付け、権限の範...', 255, '1', '0', '0', '0', 6, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:29:34', '4', '', '', '26', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (245, 'en', '116', '', 'Platform Operation', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/53b4a14293494ccf3e2f327ad39ce263.jpeg', '', '', '<p><strong>Job Responsibilities:</strong></p><p>1. Responsible for the business support work of platform operations and ensure the stable development of platform business;</p><p>2. Participate in and optimize the department\'s business operation process to ensure team collaboration;</p><p>3. Provide platform business consulting services to users;</p><p>4. Accept customer complaints and resolve them within the scope of authorization;</p><p>5. Record and edit videos of online activities, discover excellent works, and simply edit and process background information;</p><p>6. Cooperate with other departments of the company. </p><p><br /></p><p><strong>Job Requirements:</strong></p><p>1. College degree or above, love the Internet industry;</p><p>2. Strong sense of responsibility, hardworking, positive and cheerful;</p><p>3. Good image, eloquent, standard Mandarin;</p><p>4. Proficient in computer, frequent Internet access, and able to use office and other related office software;</p><p>5. Able to adapt to day and night shift work;</p><p>Note: Based on personal ability and expertise, the company will provide more development and promotion space.</p><p><br /></p><p><strong>Work Address:</strong>                        </p><h2>Beiyuan Road, Chaoyang District, Beijing</h2>', '', '', '', 'Job Responsibilities:1. Responsible for the business support work of platform operations and ensure the stable development of platform business;2. Participate in and optimize the department&#039;s business operation process to ensure team collaboration;3. Provide platform business consulting services to ...', 255, '1', '0', '0', '0', 4, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:29:49', '4', '', '', '27', '');
