INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (252, 'oe', '117', '', 'Plattformbetrieb', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/f5714df3144c33c96ef0fa0f53965a5f.jpeg', '', '', '<p><strong>Aufgaben:</strong></p><p>1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;</p><p>2. Teilnahme an und Optimierung des Geschäftsbetriebsprozesses der Abteilung, um die Zusammenarbeit im Team sicherzustellen;</p><p>3. Bereitstellung von Plattform-Geschäftsberatungsdiensten für Benutzer;</p><p>4. Entgegennahme und Lösung von Kundenbeschwerden im Rahmen der Genehmigung;</p><p>5. Aufzeichnen und Bearbeiten von Videos von Online-Aktivitäten, Entdecken hervorragender Arbeiten und einfaches Bearbeiten und Verarbeiten von Hintergrundinformationen;</p><p>6. Zusammenarbeit mit anderen Abteilungen des Unternehmens. </p><p><br /></p><p><strong>Anforderungen:</strong></p><p>1. Hochschulabschluss oder höher, Liebe zur Internetbranche;</p><p>2. Starkes Verantwortungsbewusstsein, fleißig, positiv und fröhlich;</p><p>3. Gutes Image, eloquent, Standard-Mandarin;</p><p>4. Computerkenntnisse, regelmäßiger Internetzugang und Fähigkeit, Office und andere zugehörige Bürosoftware zu verwenden;</p><p>5. Fähigkeit, sich an Tag- und Nachtschichtarbeit anzupassen;</p><p>Hinweis: Je nach persönlichen Fähigkeiten und Fachkenntnissen bietet das Unternehmen mehr Raum für Entwicklung und Aufstieg.</p><p><br /></p><p><strong>Arbeitsadresse:</strong>                        </p><h2>Beiyuan Road, Chaoyang District, Peking</h2>', '', '', '', 'Aufgaben:1. Verantwortlich für die geschäftsunterstützende Arbeit des Plattformbetriebs und Sicherstellung der stabilen Entwicklung des Plattformgeschäfts;2. Teilnahme an und Optimierung des Geschäftsbetriebsprozesses der Abteilung, um die Zusammenarbeit im Team sicherzustellen;3. Bereitstellun...', 255, '1', '0', '0', '0', 10, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:31:58', '4', '', '', '29', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (253, 'jp', '118', '', 'プラットフォーム運用', '', '', '', 'Admin', '', '', '2024-11-26 07:26:04', '/uploads/20250622/f5714df3144c33c96ef0fa0f53965a5f.jpeg', '', '', '<p><strong>職務内容:</strong></p><p>1. プラットフォーム運営の業務サポート業務を担当し、プラットフォーム事業の安定的な発展を確保する。</p><p>2. 部門の業務運営プロセスに参加し、最適化してチームのコラボレーションを確保する。</p><p>3. ユーザーにプラットフォーム事業に関するコンサルティングサービスを提供する。</p><p>4. 顧客からの苦情を受け付け、権限の範囲内で解決する。</p><p>5. オンライン活動のビデオを録画および編集し、優れた作品を発掘し、背景情報を簡単に編集および処理する。</p><p>6. 社内の他部門と協力する。</p><p><br /></p><p><strong>職務要件:</strong></p><p>1. 大学卒業以上、インターネット業界が好き。</p><p>2. 責任感が強く、勤勉、前向きで明るい。</p><p>3. イメージが良く、雄弁、標準的な中国語を話せる。</p><p>4.コンピューターに精通し、インターネットに頻繁にアクセスでき、Office およびその他の関連 Office ソフトウェアを使用できる。</p><p>5. 昼夜を問わず勤務に適応できる。</p><p>注: 個人の能力と専門知識に基づいて、会社はより多くの開発および昇進の機会を提供します。</p><p><br /></p><p><strong>勤務地住所:</strong>                            </p><h2>北京市朝陽区北園路</h2>', '', '', '', '職務内容:1. プラットフォーム運営の業務サポート業務を担当し、プラットフォーム事業の安定的な発展を確保する。2. 部門の業務運営プロセスに参加し、最適化してチームのコラボレーションを確保する。3. ユーザーにプラットフォーム事業に関するコンサルティングサービスを提供する。4. 顧客からの苦情を受け付け、権限の範...', 255, '1', '0', '0', '0', 10, 0, 0, 'Admin', 'admin', '2024-11-26 07:26:42', '2025-10-27 17:31:58', '4', '', '', '29', '');
