INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (260, 'en', '119', '', 'Nanjing xxx Construction Company official website', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/cd555fd12db37e3a91e97c17b13db4fa.jpeg', '', '', 'BadouCMS is an open-source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push notifications, carousels, multi-condition filtering, sitemaps, and more. </p><h3>Feature List</h3><ul><li>Region Management (Multi-language)</li><li>Model Management (Custom Content Model)</li><li>Model Field Management (Custom Model Fields)</li><li>Column Management</li><li>Content Management (Single Page Content, Article Content, Product Content...Custom Content Models)</li><li>Site Configuration, Company Information</li><li>Custom Tags (Custom Front-end Tags)</li><li>Front-end Template Tags</li><li>Carousel Images</li><li>Multi-condition Filtering</li><li>Website Sitemap</li><li>Friendly links</li><li>Custom forms</li><li>Messages</li><li>Article internal links</li><li>Multi-condition search</li><li>Baidu push</li><li>Content permissions</li><li>Member functions (login, register, retrieve password, change password, balance, points, logout)</li><li>Member fields</li><li>Member level (set column and content browsing permissions)</li><li>Article comments (reply, review)</li><li>My comments</li></ul>', '', '', '', 'BadouCMS is an open-source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article...', 254, '1', '0', '0', '0', 38, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-27 17:32:57', '4', '', '', '32', '');
