INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (266, 'en', '119', '', 'Wuxi xxx Construction Company Official Website 1', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/e011298e4ec8e8e20fe32e14431f9763.jpeg', '/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg,/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg', '', '<p>\nBadouCMS is the best open-source website management system based on a popular technology stack including Layui, ThinkPHP8, TypeScript, Vite, Pinia, and Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership features, article comments, internal links, Baidu push notifications, carousels, multi-condition filtering, sitemaps, and more.\n</p>\n<h3>\nFeature List 111\n</h3>\n<ul>\n<li>\nRegion Management (Multilingual)\n</li>\n<li>\nModel Management (Custom Content Model)\n</li>\n<li>\nModel Field Management (Custom Model Fields)\n</li>\n<li>\nColumn Management\n</li>\n<li>\nContent Management (Custom Content Models for Single Page Content, Article Content, Product Content, etc.)\n</li>\n<li>\nSite Configuration, Company Information\n</li>\n<li>\nCustom Tags (Custom Front-End Tags)\n</li>\n<li>\nFront-End Template Tags\n</li>\n<li>\nCarousel Images\n</li>\n<li>\nMulti-Criteria Filtering\n</li>\n<li>\nSitemap\n</li>\n<li>\nLinks\n</li>\n<li>\nCustom Forms\n</li>\n<li>\nMessage Information\n</li>\n<li>\nArticle Internal Links\n</li>\n<li>\nMulti-Criteria Search\n</li>\n<li>\nBaidu Push\n</li>\n<li>\nContent Permissions\n</li>\n<li>\nMembership Functions (Login, Register, Retrieve Password, Change Password, Balance, Points, Logout)\n</li>\n<li>\nMembership Fields\n</li>\n<li>\nMembership Level (Set Column and Content Browsing Permissions)\n</li>\n<li>\nArticle Comments (Reply, Review)\n</li>\n<li>\nMy Comments\n</li>\n</ul>', '', '', '', 'BadouCMS is the best open-source website management system based on a popular technology stack including Layui, ThinkPHP8, TypeScript, Vite, Pinia, and Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership features, article comments, ...', 251, '1', '0', '0', '0', 54, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-31 14:59:14', '4', '', '', '34', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (267, 'oe', '120', '', 'Wuxi xxx Bauunternehmen Offizielle Website 1	', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/e011298e4ec8e8e20fe32e14431f9763.jpeg', '/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg,/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg', '', '<p>\nBadouCMS ist das beste Open-Source-Website-Managementsystem und basiert auf einem beliebten Technologie-Stack, darunter Layui, ThinkPHP8, TypeScript, Vite, Pinia und Element Plus. Es unterstützt mehrere Sprachen, mehrere Modelle, Multi-Condition-Suche, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Links, Baidu-Push-Benachrichtigungen, Karussells, Multi-Condition-Filterung, Sitemaps und mehr.\n</p>\n<h3>\nFunktionsliste 111\n</h3>\n<ul>\n<li>\nRegionenverwaltung (Mehrsprachig)\n</li>\n<li>\nModellverwaltung (Benutzerdefiniertes Inhaltsmodell)\n</li>\n<li>\nModellfeldverwaltung (Benutzerdefinierte Modellfelder)\n</li>\n<li>\nSpaltenverwaltung\n</li>\n<li>\nInhaltsverwaltung (Benutzerdefinierte Inhaltsmodelle für Einzelseiteninhalte, Artikelinhalte, Produktinhalte usw.)\n</li>\n<li>\nSite-Konfiguration, Unternehmensinformationen\n</li>\n<li>\nBenutzerdefinierte Tags (Benutzerdefinierte Front-End-Tags)\n</li>\n<li>\nFront-End-Template-Tags\n</li>\n<li>\nKarussellbilder\n</li>\n<li>\nMultikriterienfilterung\n</li>\n<li>\nSitemap\n</li>\n<li>\nLinks\n</li>\n<li>\nBenutzerdefinierte Formulare\n</li>\n<li>\nNachrichteninformationen\n</li>\n<li>\nArtikelintern Links\n</li>\n<li>\nMultikriteriensuche\n</li>\n<li>\nBaidu Push\n</li>\n<li>\nInhaltsberechtigungen\n</li>\n<li>\nMitgliedschaftsfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)\n</li>\n<li>\nMitgliedschaftsfelder\n</li>\n<li>\nMitgliedsstufe (Spalten und Inhaltssuchberechtigungen festlegen)\n</li>\n<li>\nArtikelkommentare (Antworten, Überprüfen)\n</li>\n<li>\nMeine Kommentare\n</li>\n</ul>', '', '', '', 'BadouCMS ist das beste Open-Source-Website-Managementsystem und basiert auf einem beliebten Technologie-Stack, darunter Layui, ThinkPHP8, TypeScript, Vite, Pinia und Element Plus. Es unterstützt mehrere Sprachen, mehrere Modelle, Multi-Condition-Suche, Inhaltsberechtigungen, Mitgliedschaftsfunktio...', 251, '1', '0', '0', '0', 43, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-27 17:39:25', '4', '', '', '34', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (268, 'jp', '121', '', '無錫xxx建設会社公式ウェブサイト1', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/e011298e4ec8e8e20fe32e14431f9763.jpeg', '/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg,/uploads/20250622/577a43d1730d8fb8aae352738e411abf.jpeg', '', '<p>\nBadouCMSは、Layui、ThinkPHP8、TypeScript、Vite、Pinia、Element Plusなどの人気のテクノロジースタックをベースにした、最高のオープンソースウェブサイト管理システムです。複数言語、複数モデル、複数条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、内部リンク、Baiduプッシュ通知、カルーセル、複数条件フィルタリング、サイトマップなどをサポートしています。\n</p>\n<h3>\n機能一覧 111\n</h3>\n<ul>\n<li>\n地域管理（多言語）\n</li>\n<li>\nモデル管理（カスタムコンテンツモデル）\n</li>\n<li>\nモデルフィールド管理（カスタムモデルフィールド）\n</li>\n<li>\n列管理\n</li>\n<li>\nコンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツなどのカスタムコンテンツモデル）\n</li>\n<li>\nサイト設定、会社情報\n</li>\n<li>\nカスタムタグ（カスタムフロントエンドタグ）\n</li>\n<li>\nフロントエンドテンプレートタグ\n</li>\n<li>\nカルーセル画像\n</li>\n<li>\n複数条件フィルタリング\n</li>\n<li>\nサイトマップ\n</li>\n<li>\nリンク\n</li>\n<li>\nカスタムフォーム\n</li>\n<li>\nメッセージ情報\n</li>\n<li>\n記事内リンク\n</li>\n<li>\n複数条件検索\n</li>\n<li>\nBaidu Push\n</li>\n<li>\nコンテンツ権限\n</li>\n<li>\n会員機能（ログイン、登録、パスワード取得、パスワード変更、残高、ポイント、ログアウト）\n</li>\n<li>\n会員フィールド\n</li>\n<li>\n会員レベル（列とコンテンツの閲覧権限の設定）\n</li>\n<li>\n記事へのコメント（返信、レビュー）\n</li>\n<li>\n私のコメント\n</li>\n</ul>', '', '', '', 'BadouCMSは、Layui、ThinkPHP8、TypeScript、Vite、Pinia、Element Plusなどの人気のテクノロジースタックをベースにした、最高のオープンソースウェブサイト管理システムです。複数言語、複数モデル、複数条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、内部リンク、Baiduプッシュ通知、カルーセル、複数条...', 251, '1', '0', '0', '0', 44, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-29 20:41:21', '4', '', '', '34', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (269, 'en', '119', '', 'Changzhou xxx Steel Enterprise Official Website', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/11955a54eb5585a3bb436a69ffde7cc1.jpeg', '', '', 'BadouCMS is an open-source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push notifications, carousels, multi-condition filtering, sitemaps, and more. </p><h3>Feature List</h3><ul><li>Region Management (Multi-language)</li><li>Model Management (Custom Content Model)</li><li>Model Field Management (Custom Model Fields)</li><li>Column Management</li><li>Content Management (Single Page Content, Article Content, Product Content...Custom Content Models)</li><li>Site Configuration, Company Information</li><li>Custom Tags (Custom Front-end Tags)</li><li>Front-end Template Tags</li><li>Carousel Images</li><li>Multi-condition Filtering</li><li>Website Sitemap</li><li>Friendly links</li><li>Custom forms</li><li>Messages</li><li>Article internal links</li><li>Multi-condition search</li><li>Baidu push</li><li>Content permissions</li><li>Member functions (login, register, retrieve password, change password, balance, points, logout)</li><li>Member fields</li><li>Member level (set column and content browsing permissions)</li><li>Article comments (reply, review)</li><li>My comments</li></ul>', '', '', '', 'BadouCMS is an open-source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article...', 252, '1', '0', '0', '0', 30, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-11-01 08:20:41', '4', '', '', '35', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (270, 'oe', '120', '', 'Offizielle Website von Changzhou xxx Steel Enterprise', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/11955a54eb5585a3bb436a69ffde7cc1.jpeg', '', '', 'BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Multi-Condition-Suche, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu-Push-Benachrichtigungen, Karussells, Multi-Condition-Filterung, Sitemaps und mehr. </p><h3>Funktionsliste</h3><ul><li>Regionsverwaltung (mehrsprachig)</li><li>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</li><li>Modellfeldverwaltung (benutzerdefinierte Modellfelder)</li><li>Spaltenverwaltung</li><li>Inhaltsverwaltung (Einzelseiteninhalt, Artikelinhalt, Produktinhalt...benutzerdefinierte Inhaltsmodelle)</li><li>Site-Konfiguration, Unternehmensinformationen</li><li>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</li><li>Front-End-Vorlagen-Tags</li><li>Karussellbilder</li><li>Filterung nach mehreren Bedingungen</li><li>Website-Sitemap</li><li>Freundliche Links</li><li>Benutzerdefinierte Formulare</li><li>Nachrichten</li><li>Interne Artikellinks</li><li>Suche nach mehreren Bedingungen</li><li>Baidu Push</li><li>Inhaltsberechtigungen</li><li>Mitgliederfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</li><li>Mitgliederfelder</li><li>Mitgliedsebene (Spalte festlegen) und Berechtigungen zum Durchsuchen von Inhalten)</li><li>Artikelkommentare (Antworten, Überprüfen)</li><li>Meine Kommentare</li></ul>', '', '', '', 'BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Multi-Condition-Suche, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelko...', 252, '1', '0', '0', '0', 26, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-27 17:39:35', '4', '', '', '35', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (271, 'jp', '121', '', '常州xxx鋼鉄企業公式ウェブサイト', '#333333', '', '', 'admin', '本站', '', '2018-04-12 10:26:28', '/uploads/20250622/11955a54eb5585a3bb436a69ffde7cc1.jpeg', '', '', 'BadouCMSは、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plusなどの人気のテクノロジースタックをベースにしたオープンソースのウェブサイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内リンク、Baiduプッシュ通知、カルーセル、多条件フィルタリング、サイトマップなどをサポートしています。 </p><h3>機能一覧</h3><ul><li>地域管理（多言語対応）</li><li>モデル管理（カスタムコンテンツモデル）</li><li>モデルフィールド管理（カスタムモデルフィールド）</li><li>列管理</li><li>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</li><li>サイト構成、会社情報</li><li>カスタムタグ（カスタムフロントエンドタグ）</li><li>フロントエンドテンプレートタグ</li><li>カルーセル画像</li><li>複数条件フィルタリング</li><li>ウェブサイトサイトマップ</li><li>フレンドリーリンク</li><li>カスタムフォーム</li><li>メッセージ</li><li>記事内リンク</li><li>複数条件検索</li><li>Baiduプッシュ</li><li>コンテンツ権限</li><li>会員機能（ログイン、登録、パスワード取得、パスワード変更、残高、ポイント、ログアウト）</li><li>会員フィールド</li><li>メンバーレベル（列とコンテンツの閲覧権限の設定）</li><li>記事のコメント（返信、レビュー）</li><li>自分のコメント</li></ul>', '', '', '', 'BadouCMSは、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plusなどの人気のテクノロジースタックをベースにしたオープンソースのウェブサイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内リンク、Baiduプッシュ通知、カルーセル、多条件フィ...', 252, '1', '0', '0', '0', 26, 0, 0, 'admin', 'admin', '2018-04-12 10:32:52', '2025-10-27 17:39:35', '4', '', '', '35', '');
