INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (275, 'en', '85', '', 'Company Profile', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:26:11', '', '', '', '<p><br /></p><h3>Introduction</h3><p>BadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comments, article internal links, Baidu push, carousel, multi-condition filtering, site map, etc. </p><h3>Feature List</h3><ul class=\"list-paddingleft-2\"><li><p>Region management (multi-language)</p></li><li><p>Model management (custom content model)</p></li><li><p>Model field management (custom model field)</p></li><li><p>Column management</p></li><li><p>Content management (single page content, article content, product content...custom content model)</p></li><li><p>Site configuration, company information</p></li><li><p>Custom tags (custom front-end tags)</p></li><li><p>Front-end template tags</p></li><li><p>Carousel images</p></li><li><p>Multi-condition filtering</p></li><li ><p>Sitemap</p></li><li><p>Friendly Links</p></li><li><p>Custom Forms</p></li><li><p>Messages</p></li><li><p>Article Internal Links</p></li><li><p>Multi-condition Search</p></li><li><p>Content Permissions</p></li><li><p>Membership Functions (Login, Register, Retrieve Password, Change Password, Balance, Points, Logout)</p></li><li><p>Membership Fields</p></li><li><p>Membership Levels (Set Columns and Content Browsing Permissions)</p></li><li><p>Article Comments (Reply, Review)</p></li><li><p>My Comments</p></li></ul>', '', '', '', 'IntroductionBadouCMS is an open source website management system based on popular technology stacks such as Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus. It supports multiple languages, multiple models, multi-condition search, content permissions, membership functions, article comme...', 255, '1', '0', '0', '0', 2731, 0, 0, 'admin', 'admin', '2018-04-11 17:26:11', '2025-11-03 18:46:46', '4', '', '', '36', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (276, 'oe', '86', '', 'Unternehmensprofil', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:26:11', '', '', '', '<p><br /></p><h3>Einführung</h3><p>BadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsfunktionen, Artikelkommentare, interne Artikellinks, Baidu Push, Karussell, Filterung mit mehreren Bedingungen, Sitemap usw. </p><h3>Funktionsliste</h3><ul class=\"list-paddingleft-2\"><li><p>Regionsverwaltung (mehrsprachig)</p></li><li><p>Modellverwaltung (benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Modellfeldverwaltung (benutzerdefiniertes Modellfeld)</p></li><li><p>Spaltenverwaltung</p></li><li><p>Inhaltsverwaltung (Einzelseiteninhalt, Artikelinhalt, Produktinhalt ... benutzerdefiniertes Inhaltsmodell)</p></li><li><p>Site-Konfiguration, Unternehmensinformationen</p></li><li><p>Benutzerdefinierte Tags (benutzerdefinierte Front-End-Tags)</p></li><li><p>Front-End-Vorlagen-Tags</p></li><li><p>Karussellbilder</p></li><li><p>Filterung mit mehreren Bedingungen</p></li><li ><p>Sitemap</p></li><li><p>Freundliche Links</p></li><li><p>Benutzerdefinierte Formulare</p></li><li><p>Nachrichten</p></li><li><p>Interne Artikellinks</p></li><li><p>Suche mit mehreren Bedingungen</p></li><li><p>Inhaltsberechtigungen</p></li><li><p>Mitgliedschaftsfunktionen (Anmelden, Registrieren, Passwort abrufen, Passwort ändern, Guthaben, Punkte, Abmelden)</p></li><li><p>Mitgliedschaftsfelder</p></li><li><p>Mitgliedschaftsstufen (Spalten und Berechtigungen zum Durchsuchen von Inhalten festlegen)</p></li><li><p>Artikelkommentare (Antworten, Überprüfen)</p></li><li><p>Meine Kommentare</p></li></ul>', '', '', '', 'EinführungBadouCMS ist ein Open-Source-Website-Managementsystem, das auf gängigen Technologie-Stacks wie Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus basiert. Es unterstützt mehrere Sprachen, mehrere Modelle, Suche mit mehreren Bedingungen, Inhaltsberechtigungen, Mitgliedschaftsf...', 255, '1', '0', '0', '0', 2641, 0, 0, 'admin', 'admin', '2018-04-11 17:26:11', '2025-11-03 18:46:51', '4', '', '', '36', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (277, 'jp', '87', '', '会社概要', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:26:11', '', '', '', '<p><br /></p><h3>はじめに</h3><p>BadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多条件フィルタリング、サイトマップなどをサポートしています。</p><h3>機能一覧</h3><ul class=\"list-paddingleft-2\"><li><p>地域管理（多言語）</p></li><li><p>モデル管理（カスタムコンテンツモデル）</p></li><li><p>モデルフィールド管理（カスタムモデルフィールド）</p></li><li><p>列管理</p></li><li><p>コンテンツ管理（シングルページコンテンツ、記事コンテンツ、商品コンテンツ...カスタムコンテンツモデル）</p></li><li><p>サイト構成、会社情報</p></li><li><p>カスタムタグ（カスタムフロントエンドタグ）</p></li><li><p>フロントエンドテンプレートタグ</p></li><li><p>カルーセル画像</p></li><li><p>多条件フィルタリング</p></li><li ><p>サイトマップ</p></li><li><p>フレンドリーリンク</p></li><li><p>カスタムフォーム</p></li><li><p>メッセージ</p></li><li><p>記事内リンク</p></li><li><p>複数条件検索</p></li><li><p>コンテンツ権限</p></li><li><p>メンバーシップ機能（ログイン、登録、パスワードの取得、パスワードの変更、残高、ポイント、ログアウト）</p></li><li><p>メンバーシップフィールド</p></li><li><p>メンバーシップレベル（列とコンテンツの閲覧権限の設定）</p></li><li><p>記事へのコメント（返信、レビュー）</p></li><li><p>私のコメント</p></li></ul>', '', '', '', 'はじめにBadouCMS は、Vue3.3 + ThinkPHP8 + TypeScript + Vite + Pinia + Element Plus などの人気のテクノロジー スタックをベースにしたオープン ソースの Web サイト管理システムです。多言語、多モデル、多条件検索、コンテンツ権限、メンバーシップ機能、記事コメント、記事内部リンク、百度プッシュ、カルーセル、多...', 255, '1', '0', '0', '0', 2643, 0, 0, 'admin', 'admin', '2018-04-11 17:26:11', '2025-11-04 14:45:08', '4', '', '', '36', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (279, 'oe', '126', '', 'Kontaktieren Sie uns', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:31:29', '/static/upload/image/20180413/1523583018133454.png', '', '', 'Kontaktieren Sie uns', '', '', '', 'Offizielle Website: www.badoucms.com Technische Austauschgruppe: 137083872www.badoucms.com Wir haben immer an dem Konzept festgehalten, dass Einfachheit der Schlüssel ist und Teilen die Welt verändern kann, und bestehen darauf, die einfachste und flexibelste Badoucms-Open-Source-Software zu entwickeln!', 255, '1', '0', '0', '0', 133, 0, 0, 'admin', 'admin', '2018-04-11 17:31:29', '2025-10-31 17:51:59', '4', '', '', '37', '');
INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (280, 'jp', '127', '', 'お問い合わせ', '#333333', '', '', 'admin', '本站', '', '2018-04-11 17:31:29', '/static/upload/image/20180413/1523583018133454.png', '', '', 'お問い合わせ', '', '', '', '公式サイト: www.badoucms.com 技術交流グループ: 137083872www.badoucms.com 私たちは常に、シンプルさが鍵であり、共有することで世界を変えることができるという概念を堅持し、最もシンプルで柔軟な badoucms オープンソースソフトウェアの作成にこだわっています。', 255, '1', '0', '0', '0', 133, 0, 0, 'admin', 'admin', '2018-04-11 17:31:29', '2025-10-31 17:52:03', '4', '', '', '37', '');
