INSERT INTO `__PREFIX__cms_content` (`id`, `acode`, `scode`, `subscode`, `title`, `titlecolor`, `subtitle`, `filename`, `author`, `source`, `outlink`, `date`, `ico`, `pics`, `picstitle`, `content`, `tags`, `enclosure`, `keywords`, `description`, `sorting`, `status`, `istop`, `isrecommend`, `isheadline`, `visits`, `likes`, `oppose`, `create_user`, `update_user`, `create_time`, `update_time`, `gtype`, `gid`, `gnote`, `aucode`, `custom_tpl`) VALUES (287, 'en', '101', '', 'A black and white striped suit collar with three-quarter sleeves and a cinched w...', '', '', '', '', '', '', '2025-10-29 08:44:47', '/uploads/20251029/2e6c6158799c82f7e301f7804f841035.jpeg', '/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/f8b41f2de9b3394d6e107427e27287dd.jpg,/uploads/20251026/efe7de20e7e930334b098bf9a6d528f0.jpg', '', '<p><span style=\"font-size: 36px;\"></span></p>\n<section>\n <span style=\"font-size: 18px;\">Company Profile: Qianyan Zhinong is a leading provider of full life-cycle services for smart greenhouses in China. It has been deeply engaged in the application of BIM and GIS technologies, led the completion of the country\'s first BIM pipipe integrated design greenhouse and the first GIS construction review project, and participated in the compilation of agricultural standards and norms. It is committed to promoting agricultural engineering innovation with digital technology.</span>\n</section>\n<p><br><span style=\"font-size: 36px;\"></span></p>\n<p><br></p>\n<p><br></p>\n<p><br></p>\n<section style=\"-webkit-tap-highlight-color: transparent; margin: 0px 10px; padding: 0px; outline: 0px; max-width: 100%; box-sizing: border-box; overflow-wrap: break-word !important;\">\n <section style=\"-webkit-tap-highlight-color: transparent; margin: 0px; padding: 0px; outline: 0px; max-width: 100%; box-sizing: border-box !important; overflow-wrap: break-word !important;\">\n  <section data-id=\"134375\" style=\"-webkit-tap-highlight-color: transparent; margin: 0