INSERT INTO `__PREFIX__cms_site` (`id`, `acode`, `title`, `subtitle`, `domain`, `logo`, `keywords`, `description`, `icp`, `theme`, `statistical`, `copyright`) VALUES (1, 'cn', 'BadouCMS网站管理系统', 'BadouCMS', 'localhost', '/uploads/20250622/83f3aee5bdea54e652ef497fc45f4ab7.png', 'cms,免费cms,开源cms,企业cms,建站cms', 'BadouCMS是一套全新内核且永久开源免费的PHP企业网站开发建设管理系统，是一套高效、简洁、 强悍的可免费商用的PHP CMS源码，能够满足各类企业网站开发建设的需要。系统采用简单到想哭的模板标签，只要懂HTML就可快速开发企业网站。官方提供了大量网站模板免费下载和使用，将致力于为广大开发者和企业提供最佳的网站开发建设解决方案。', '苏ICP备88888888号', 'inquiry', '', 'BadouCMS All Rights Reserved.');
