DROP TABLE IF EXISTS `__PREFIX__cms_content_sort`;
CREATE TABLE `__PREFIX__cms_content_sort` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT COMMENT '编号',
  `acode` varchar(20) NOT NULL COMMENT '区域编码',
